    class GameEvent {
        static on(ev, caller, listener) {
            this.dispatcher.on(ev, caller, listener);
        }
        static off(ev, caller, listener) {
            this.dispatcher.off(ev, caller, listener);
        }
        static ev(ev, data) {
            return this.dispatcher.event(ev, data);
        }
        static has(ev) {
            return this.dispatcher.hasListener(ev);
        }
    }
    GameEvent.dispatcher = new Laya.EventDispatcher();

    class Util {
        static randomRange(min, max) {
            return Math.random() * (max - min) + min;
        }
        static randomRangeInt(min, max) {
            return Math.round(Math.random() * (max - min) + min);
        }
        static RandomInt(min, max) {
            let length = max - min;
            return Math.floor(Math.random() * length + min);
        }
        static getRandomArrElement(arr, count) {
            let shuffled = arr.slice(0),
                i = arr.length,
                min = i - count,
                temp, index;
            while (i > min) {
                index = Math.floor((i--) * Math.random());
                temp = shuffled[index];
                shuffled[index] = shuffled[i];
                shuffled[i] = temp;
            }
            return shuffled.slice(min);
        }
        static getRandomArrElement2(arr, count) {
            let shuffled = arr.slice(0),
                i = arr.length,
                min = i - count,
                temp, index;
            if (arr.length <= count) {
                return shuffled.slice(0);
            }
            while (i > min) {
                index = Math.floor((i--) * Math.random());
                temp = shuffled[index];
                shuffled[index] = shuffled[i];
                shuffled[i] = temp;
            }
            return shuffled.slice(min);
        }
        static getMaxNumber(arr) {
            let max = 0;
            for (let i = 0; i < arr.length; i++) {
                if (arr[i] > max) {
                    max = arr[i] + 0;
                }
            }
            return max;
        }
        static Clamp(value, min, max) {
            if (value < min) {
                return min;
            } else {
                return value > max ? max : value;
            }
        }
        static findChild(sp, name) {
            if (sp.name == name)
                return sp;
            else
                return this._innerFindChild(sp._children, name);
        }
        static _innerFindChild(spArr, name) {
            var arr = [];
            for (var i = 0; i < spArr.length; i++) {
                var child = spArr[i];
                if (child.name == name) {
                    return child;
                } else if (child.numChildren) {
                    arr = arr.concat(child._children);
                }
            }
            if (!arr.length)
                return null;
            return this._innerFindChild(arr, name);
        }
        static checkPlatform(platfom) {return false;}
        static checkDouYin() {return true;}
        static getScreenPosition(camera, position) {
            let screenPosition = new Laya.Vector4();
            camera.worldToViewportPoint(position, screenPosition);
            return screenPosition;
        }
        static ThreeD2TwoD(camera, e) {
            let t = new Laya.Vector4(0, 0, 0, 0);
            camera.viewport.project(e, camera.projectionViewMatrix, t);
            t.x /= Laya.stage.clientScaleX;
            t.y /= Laya.stage.clientScaleY;
            return t;
        }
        static twoPointDistance(a, b) {
            let x = a.x - b.x;
            let y = a.y - b.y;
            let res = Math.sqrt(x * x + y * y);
            return res;
        }
        static inCubeArea(a, cube, xlength, ylength) {
            let dx = Math.abs(a.x - cube.x);
            let dy = Math.abs(a.y - cube.y);
            let res = (dx <= xlength) && (dy <= ylength);
            return res;
        }
        static travelSprite3D(root, func) {
            if (!root)
                return;
            func(root);
            for (let i = 0; i < root.numChildren; i++) {
                this.travelSprite3D(root.getChildAt(i), func);
            }
        }
        static ttCapScreen() {
            return new Promise((reslove) => {
                let gl = Laya["LayaGL"].instance;
                let pixels = new Uint8Array(gl.drawingBufferWidth * gl.drawingBufferHeight * 4);
                gl.readPixels(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
                let w = gl.drawingBufferWidth;
                let h = gl.drawingBufferHeight;
                let texture2d = new Laya.Texture2D(w, h, Laya.TextureFormat.R8G8B8A8, false, false);
                texture2d.setPixels(pixels);
                let tex = new Laya.Texture(texture2d);
                reslove(tex);
            });
        }
        static TimerFormatByHM(num = 0) {
            let second = Math.floor(num % 60);
            if (second <= 9)
                second = '0' + second;
            return `${second}`;
        }
        static TimerFormat(num = 0) {
            let minute = Math.floor(num / 60);
            let second = Math.floor(num % 60);
            if (minute <= 9)
                minute = '0' + minute;
            if (second <= 9)
                second = '0' + second;
            return `${minute}:${second}`;
        }
        static TimerFormatHour(num = 0) {
            let hour = 0 + '';
            let minute = Math.floor(num / 60);
            let second = Math.floor(num % 60);
            hour = Math.floor(minute / 60);
            minute = Math.floor(minute % 60);
            if (hour <= 9)
                hour = '0' + hour;
            if (minute <= 9)
                minute = '0' + minute;
            if (second <= 9)
                second = '0' + second;
            return `${hour}:${minute}:${second}`;
        }
        static ContrastDay(time1, time2) {
            let signDate = new Date(time1);
            let now = new Date(time2);
            if (now.getFullYear() != signDate.getFullYear() || now.getMonth() != signDate.getMonth() || now.getDate() != signDate.getDate()) {
                return false;
            } else {
                return true;
            }
        }
        static CutString(string, count = 4) {
            if (string.length <= count)
                return string;
            return string.substring(0, count) + "...";
        }
        static effectNumberChange(info) {
            let obj = {
                v: info.from
            };
            Laya.Tween.to(obj, {
                v: info.to
            }, info.duration, null, Laya.Handler.create(this, () => {
                if (info.complete)
                    try {
                        info.complete();
                    }
                catch (e) {}
            })).update = Laya.Handler.create(this, () => {
                try {
                    info.update(obj.v);
                } catch (e) {}
            }, null, false);
            return {
                stop: () => {
                    Laya.Tween.clearAll(obj);
                }
            };
        }
        static CreateBezierPoints(anchorpoints, pointsAmount = 20) {
            var points = [];
            for (var i = 0; i < pointsAmount; i++) {
                var point = this._multiPointBezier(anchorpoints, i / pointsAmount);
                points.push(point);
            }
            return points;
        }
        static _multiPointBezier(points, t) {
            var len = points.length;
            var x = 0,
                y = 0;
            var erxiangshi = function (start, end) {
                var cs = 1,
                    bcs = 1;
                while (end > 0) {
                    cs *= start;
                    bcs *= end;
                    start--;
                    end--;
                }
                return (cs / bcs);
            };
            for (var i = 0; i < len; i++) {
                var point = points[i];
                x += point.x * Math.pow((1 - t), (len - 1 - i)) * Math.pow(t, i) * (erxiangshi(len - 1, i));
                y += point.y * Math.pow((1 - t), (len - 1 - i)) * Math.pow(t, i) * (erxiangshi(len - 1, i));
            }
            return {
                x: x,
                y: y
            };
        }
        static chooseArrExpert(arrValue, values) {
            if (!arrValue || arrValue.length <= 0) {
                return;
            }
            let newArr = [].concat(arrValue);
            for (let i = 0; i < newArr.length; i++) {
                const value = newArr[i];
                if (values && values.indexOf(value) != -1) {
                    newArr.splice(i, 1);
                    i--;
                }
            }
            return newArr;
        }
        static getRandomInfo(arr) {
            if (!arr)
                return null;
            let len = arr.length;
            let index = Math.random() * len;
            index = Math.floor(index);
            return arr[index];
        }
        static redTipsAnim(box) {
            let tween = Laya.Tween.to(box, {
                rotation: 30
            }, 50, Laya.Ease.backIn, Laya.Handler.create(this, () => {}));
            tween.repeat = 0;
            return tween;
        }
        static copyObject(obj) {
            let newObj = {};
            if (typeof obj !== 'object') {
                return obj;
            } else {
                for (const key in obj) {
                    if (Object.prototype.hasOwnProperty.call(obj, key)) {
                        const element = obj[key];
                        if (element === newObj) {
                            continue;
                        }
                        newObj[key] = Util.copyObject(element);
                    }
                }
            }
            return newObj;
        }
        get FrameDelta() {
            let d = Laya.timer.delta;
            if (d > 100)
                d = 16;
            if (d < 16)
                d = 16;
            return d;
        }
        static isCollsionWithRect(rect1, rect2) {
            if (!rect1 || !rect2) {
                return false;
            }
            return rect1.intersects(rect2);
        }
    }

