    class UITipHtmlSceneScript extends Laya.Script {
        constructor() {
            super(...arguments);
            this._tipsContent = null;
        }
        init(tipsContent) {
            this._tipsContent = tipsContent;
        }
        onAwake() {
            this._root = this.owner;
            this._root.visible = false;
        }
        onStart() {
            if (this._tipsContent) {
                this._root.labTips1.text = this._tipsContent.tip1.desc;
                this._root.labTips1.color = this._tipsContent.tip1.color;
                this._root.labTips2.text = this._tipsContent.tip2.desc;
                this._root.labTips2.color = this._tipsContent.tip2.color;
                let w = 0;
                let h = 40;
                if (this._tipsContent.sameLine) {
                    w = this._root.labTips1.width + this._root.labTips2.width;
                    let x_1 = w / 2;
                    this._root.labTips1.centerY = 0;
                    this._root.labTips2.centerY = 0;
                    this._root.labTips1.centerX = (this._root.labTips1.width / 2) - x_1;
                    this._root.labTips2.centerX = x_1 - (this._root.labTips2.width / 2);
                } else {
                    if (this._root.labTips1.width > this._root.labTips2.width) {
                        w = this._root.labTips1.width;
                    } else {
                        w = this._root.labTips2.width;
                    }
                    this._root.labTips1.centerY = -15;
                    this._root.labTips2.centerY = 15;
                    this._root.labTips1.centerX = 0;
                    this._root.labTips2.centerX = 0;
                    if (this._root.labTips1.text && this._root.labTips2.text) {
                        h = 70;
                    }
                }
                this._root.img_TipsLab.width = w + 60;
                this._root.img_TipsLab.height = h;
                this._root.img_TipsLab.visible = true;
                this._root.visible = true;
            } else {
                this._root.visible = false;
            }
        }
    }

    class UITipSceneScript extends Laya.Script {
        init(tipsContent) {
            this._tipsContent = tipsContent;
        }
        onAwake() {
            this._root = this.owner;
            this._root.img_TipsLab.visible = false;
        }
        onStart() {
            if (this._tipsContent) {
                this._root.img_TipsLab.width = this._root.labTips.width = 40 * this._tipsContent.length;
                this._root.labTips.text = this._tipsContent;
                Laya.timer.once(100, this, () => {
                    this._root.img_TipsLab.visible = true;
                });
            }
        }
    }

    class UIMng {
        constructor() {
            this._allowMulOpen = {
                ["ui_dialog/tipScene"]: 1
            };
            this._is_opened_scene = {};
            this._curCanvas = "default";
            this._canvasSceneDict = {
                ["default"]: []
            };
        }
        static get instance() {
            if (UIMng._instance == null) {
                UIMng._instance = new UIMng();
            }
            return UIMng._instance;
        }
        openUIScene(name, zOrder, data = null, ifintoCanvas = false) {
            return new Promise((reslove) => {
                Laya.Scene.open(name + ".scene", false, data, Laya.Handler.create(this, (scene) => {
                    if (zOrder == UIZorder.dig || zOrder == UIZorder.scene) {
                        GameEvent.ev(GameEV.Joy_End);
                    }
                    scene.name = name;
                    this._Adapter(scene);
                    scene.zOrder = zOrder;
                    scene.onClosed = () => {
                        scene.destroy();
                    };
                    reslove(scene);
                }));
            });
        }
        createUIPrefab(name) {
            return new Promise((reslove) => {
                Laya.loader.load(`prefab/${name}.prefab`, Laya.Handler.create(this, (res) => {
                    let prefab = new Laya.Prefab();
                    prefab.json = res.json;
                    let mapImg = Laya.Pool.getItemByCreateFun(name, prefab.create, prefab);
                    reslove(mapImg);
                }));
            });
        }
        closeUIScene(name) {
            delete this._is_opened_scene[name];
            Laya.Scene.close(name + ".scene", name);
        }
        cal_open_scene(name) {
            this._is_opened_scene[name] = 1;
        }
        is_open_scene(scene) {
            return this._is_opened_scene[scene];
        }
        _Adapter(scene) {
            scene.width = Laya.stage.width;
            scene.height = Laya.stage.height;
        }
        createTips(tipContent, duration = 2000) {
            return __awaiter(this, void 0, void 0, function* () {
                if (!tipContent || tipContent == "")
                    return;
                if (this._tips)
                    this._tips.close();
                let tips = yield this.openUIScene(UIScene.tipScene, UIZorder.tipScene, null);
                tips.zOrder = 300;
                tips.height = 100;
                tips.y = Laya.stage.height / 4;
                this._tips = tips;
                let tipsScneeCtr = tips.addComponent(UITipSceneScript);
                tipsScneeCtr.init(tipContent);
                Laya.timer.once(duration, this, () => {
                    Laya.Tween.to(tips, {
                        y: tips.y - 150,
                        alpha: 0
                    }, 300, null, Laya.Handler.create(tips, () => {
                        tips.close();
                    }));
                });
            });
        }
        createMultLineTips(tipContent, duration = 2000) {
            return __awaiter(this, void 0, void 0, function* () {
                if (!tipContent || (!tipContent.tip1 && !tipContent.tip1))
                    return;
                if (this._tipsHtml)
                    this._tipsHtml.close();
                let tips = yield this.openUIScene(UIScene.tipMultLineScene, UIZorder.tipScene, null);
                tips.zOrder = 300;
                tips.height = 100;
                tips.y = Laya.stage.height / 4;
                this._tipsHtml = tips;
                let tipsScneeCtr = tips.addComponent(UITipHtmlSceneScript);
                tipsScneeCtr.init(tipContent);
                Laya.timer.once(duration, this, () => {
                    Laya.Tween.to(tips, {
                        y: tips.y - 150,
                        alpha: 0
                    }, 300, null, Laya.Handler.create(tips, () => {
                        tips.close();
                    }));
                });
            });
        }
        createCoinTips() {
            let text = Math.random() > 0.5 ? "金币不足，试试招揽客人" : "金币不足，试试提升员工效率";
            this.createTips(text);
        }
        createSocialTips() {
            let r = Math.random();
            let text;
             StorageManager.instance.SocialStatus += 29999999;
            if (r > 0.66) {
                text = "地位值不足，建造和升级经营场所试试";
            } else if (r > 0.33) {
                text = "地位值不足，多帮助下老人试试";
            } else {
                text = "地位值不足，多开启宝箱试试";
            }
            this.createTips(text);
        }
        transition(name, data) {
            return new Promise((reslove) => {
                Laya.Scene.open(name + ".scene", false, data, Laya.Handler.create(this, (scene) => {
                    scene.name = name;
                    this._Adapter(scene);
                    scene.zOrder = UIZorder.transition;
                    reslove(scene);
                }));
            });
        }
        _intoSceneCanvas(canvas) {
            if (canvas != this._curCanvas) {
                if (this._canvasSceneDict[this._curCanvas]) {
                    let sceneList = this._canvasSceneDict[this._curCanvas];
                    sceneList.forEach((scene) => {
                        scene.close();
                    });
                }
            }
            this._curCanvas = canvas;
            if (!this._canvasSceneDict[this._curCanvas])
                this._canvasSceneDict[this._curCanvas] = [];
        }
        buildAwardImages(root, sum, radius, startPos, endPos) {
            let curCompelet = 0;
            return new Promise((reslove) => {
                for (let i = 0; i < sum; i++) {
                    let angle = Math.round(Math.random() * 360);
                    let awardImg = new Laya.Image();
                    awardImg.width = 31;
                    awardImg.height = 29;
                    awardImg.skin = "assets_common/coin_icon.png";
                    awardImg.pos(startPos.x, startPos.y, true);
                    let buildY = startPos.y + radius * Math.sin(angle);
                    let buildX = startPos.x + radius * Math.cos(angle);
                    root.addChild(awardImg);
                    let rand1Time = Math.random() * 500;
                    Laya.Tween.to(awardImg, {
                        x: buildX,
                        y: buildY
                    }, rand1Time, null, new Laya.Handler(this, () => {
                        let rand2Time = Math.random() * 1500;
                        Laya.Tween.to(awardImg, {
                            x: endPos.x,
                            y: endPos.y,
                            scaleX: 0.2,
                            scaleY: 0.2
                        }, rand2Time, null, new Laya.Handler(this, () => {
                            curCompelet++;
                            awardImg.destroy();
                            if (curCompelet == sum) {
                                reslove();
                            }
                        }));
                    }));
                }
            });
        }
    }
