    class L3D extends Laya.Handler {
        static onclick(listener, ths, handler, args) {
            listener.on(Laya.Event.CLICK, ths, handler, args);
        }
        static offclick(listener, ths, handler) {
            listener.off(Laya.Event.CLICK, ths, handler);
        }
        static ondown(listener, ths, handler) {
            listener.on(Laya.Event.MOUSE_DOWN, ths, handler);
        }
        static offdown(listener, ths, handler) {
            listener.off(Laya.Event.MOUSE_DOWN, ths, handler);
        }
        static onmove(listener, ths, handler, args) {
            listener.on(Laya.Event.MOUSE_MOVE, ths, handler, args);
        }
        static offmove(listener, ths, handler) {
            listener.off(Laya.Event.MOUSE_MOVE, ths, handler);
        }
        static onup(listener, ths, handler) {
            listener.on(Laya.Event.MOUSE_UP, ths, handler);
        }
        static offup(listener, ths, handler) {
            listener.off(Laya.Event.MOUSE_UP, ths, handler);
        }
        static onout(listener, ths, handler) {
            listener.on(Laya.Event.MOUSE_OUT, ths, handler);
        }
        static offout(listener, ths, handler) {
            listener.off(Laya.Event.MOUSE_OUT, ths, handler);
        }
        static createloop(caller, method, args) {
            return L3D.create(caller, method, args, false);
        }
        static createGrayFilter() {
            let gray = new Laya.ColorFilter([
                0.3086, 0.6094, 0.0820, 0, 0,
                0.3086, 0.6094, 0.0820, 0, 0,
                0.3086, 0.6094, 0.0820, 0, 0,
                0, 0, 0, 1, 0
            ]);
            return [gray];
        }
    }

    class DailyTaskDialogUI extends ui.ui_dialog.DailyTaskDialogUI {
        constructor() {
            super(...arguments);
            this._config = [];
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.daily_task);
            this._initView();
        }
        onEnable() {
            L3D.onclick(this.bg, this, this._bgClick);
            L3D.onclick(this.closeBtn, this, this._closeBtnClick);
            L3D.onclick(this.woodBoxBtn, this, this._getEnergyClick);
            L3D.onclick(this.bronzeBoxBtn, this, this._getEnergyClick);
            L3D.onclick(this.goldBoxBtn, this, this._getEnergyClick);
            GameEvent.on(GameEV.dailyTaskEnergyUpdate, this, this._dailyTaskEnergyUpdateEvent);
            GameEvent.on(GameEV.dailyTaskUpdate, this, this._dailyTaskUpdateEvent);
            GameEvent.on(GameEV.dailyTaskEnergyBox, this, this._dailyTaskEnergyBoxEvent);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this._bgClick);
            L3D.offclick(this.closeBtn, this, this._closeBtnClick);
            L3D.offclick(this.woodBoxBtn, this, this._getEnergyClick);
            L3D.offclick(this.bronzeBoxBtn, this, this._getEnergyClick);
            L3D.offclick(this.goldBoxBtn, this, this._getEnergyClick);
            GameEvent.off(GameEV.dailyTaskEnergyUpdate, this, this._dailyTaskEnergyUpdateEvent);
            GameEvent.off(GameEV.dailyTaskUpdate, this, this._dailyTaskUpdateEvent);
            GameEvent.off(GameEV.dailyTaskEnergyBox, this, this._dailyTaskEnergyBoxEvent);
        }
        _bgClick() {
            this.closeView();
        }
        _closeBtnClick() {
            this.closeView();
        }
        _getEnergyClick(args) {
            let target = args.target;
            let isGet = false;
            let info = DailyTaskManager.Instance.getEnergyInfo(1);
            switch (target) {
                case this.woodBoxBtn:
                    if (info && info.target <= StorageManager.instance.DailyEnergy &&
                        !StorageManager.instance.getDailyEnergyGet(info.id)) {
                        this.woodBox_Anim.stop();
                        isGet = true;
                        StorageManager.instance.setDailyEnergyGet(info.id);
                    } else {
                        UIMng.instance.createTips("不可领取");
                    }
                    break;
                case this.bronzeBoxBtn:
                    info = DailyTaskManager.Instance.getEnergyInfo(2);
                    if (info && info.target <= StorageManager.instance.DailyEnergy &&
                        !StorageManager.instance.getDailyEnergyGet(info.id)) {
                        this.bronzeBox_Anim.stop();
                        isGet = true;
                        StorageManager.instance.setDailyEnergyGet(info.id);
                    } else {
                        UIMng.instance.createTips("不可领取");
                    }
                    break;
                case this.goldBoxBtn:
                    info = DailyTaskManager.Instance.getEnergyInfo(3);
                    if (info && info.target <= StorageManager.instance.DailyEnergy &&
                        !StorageManager.instance.getDailyEnergyGet(info.id)) {
                        this.gold_Anim.stop();
                        isGet = true;
                        StorageManager.instance.setDailyEnergyGet(info.id);
                    } else {
                        UIMng.instance.createTips("不可领取");
                    }
                    break;
                default:
                    break;
            }
            if (isGet && info) {
                ModuleReportManager.inst.updateStorage(ModuleReportName.daily_task, info.id);
                DailyTaskManager.Instance.sendEnergyReward(info.id);
            }
        }
        _dailyTaskEnergyUpdateEvent() {
            this._updateEnergy();
        }
        _dailyTaskUpdateEvent() {
            this.taskList.array = this._config;
        }
        _dailyTaskEnergyBoxEvent() {
            this._updateEnergy();
        }
        _updateEnergy() {
            this.energyFontLabel.value = StorageManager.instance.DailyEnergy + '';
            let off = 60;
            let w = StorageManager.instance.DailyEnergy / 80 * (454 - 60) + off;
            if (w >= 454)
                w = 454;
            if (w < 60)
                w = 60;
            this.energyProgress.width = w;
            let len = DailyTaskManager.Instance.energyConfig.length;
            for (let i = 0; i < len; i++) {
                const info = DailyTaskManager.Instance.energyConfig[i];
                if (info.target > StorageManager.instance.DailyEnergy) {
                    if (info.target == 25) {
                        this.setEnergyBoxState(this.woodBoxBtn, 1);
                    } else if (info.target == 50) {
                        this.setEnergyBoxState(this.bronzeBoxBtn, 1);
                    } else if (info.target == 80) {
                        this.setEnergyBoxState(this.goldBoxBtn, 1);
                    }
                } else {
                    if (StorageManager.instance.getDailyEnergyGet(info.id)) {
                        if (info.target == 25) {
                            this.setEnergyBoxState(this.woodBoxBtn, 3);
                        } else if (info.target == 50) {
                            this.setEnergyBoxState(this.bronzeBoxBtn, 3);
                        } else if (info.target == 80) {
                            this.setEnergyBoxState(this.goldBoxBtn, 3);
                        }
                    } else {
                        if (info.target == 25) {
                            this.woodBox_Anim.play(0, true);
                            this.setEnergyBoxState(this.woodBoxBtn, 2);
                        } else if (info.target == 50) {
                            this.bronzeBox_Anim.play(0, true);
                            this.setEnergyBoxState(this.bronzeBoxBtn, 2);
                        } else if (info.target == 80) {
                            this.gold_Anim.play(0, true);
                            this.setEnergyBoxState(this.goldBoxBtn, 2);
                        }
                    }
                }
            }
        }
        setEnergyBoxState(box, state) {
            let hasGet = box.getChildByName("hasGet");
            let waitGet = box.getChildByName("waitGet");
            if (state == 2) {
                waitGet.visible = true;
                hasGet.visible = false;
            } else if (state == 3) {
                hasGet.visible = true;
                waitGet.visible = false;
            } else {
                hasGet.visible = false;
                waitGet.visible = false;
            }
        }
        _render(cell, index) {
            let data = cell.dataSource;
            let icon1 = cell.getChildByName("icon1");
            let icon2 = cell.getChildByName("icon2");
            this._setTaskRewardInfo(icon1, data.reward[0]);
            this._setTaskRewardInfo(icon2, data.reward[1]);
            let taskDescLabel = cell.getChildByName("taskDescLabel");
            taskDescLabel.text = data.targetDesc.replace("&", data.target + '');
            let proNum = StorageManager.instance.getDailyTaskProgress(data.id);
            let prgress = cell.getChildByName("prgress");
            let pro = prgress.getChildByName("pro");
            let proRate = proNum / data.target;
            if (proRate <= 0)
                proRate = 0;
            if (proRate >= 1)
                proRate = 1;
            pro.scaleX = proRate;
            let prgressLabel = prgress.getChildByName("prgressLabel");
            prgressLabel.text = proNum + "/" + data.target;
            let getBtn = cell.getChildByName("getBtn");
            let goBtn = cell.getChildByName("goBtn");
            let hasGet = cell.getChildByName("hasGet");
            getBtn.visible = false;
            goBtn.visible = false;
            hasGet.visible = false;
            if (StorageManager.instance.getDailyTaskGet(data.id)) {
                hasGet.visible = true;
            } else if (proNum >= data.target) {
                getBtn.visible = true;
                getBtn.on(Laya.Event.CLICK, this, this._getBtnClick, [data]);
            } else {
                goBtn.visible = true;
                goBtn.on(Laya.Event.CLICK, this, this._goBtnClick, [data]);
            }
        }
        _getBtnClick(data) {
            DailyTaskManager.Instance.sendReward(data);
        }
        _goBtnClick(data) {
            UIMng.instance.createTips(data.goDesc);
        }
        _setTaskRewardInfo(node, info = null) {
            if (info) {
                let icon = node.getChildByName("icon");
                let numLabel = node.getChildByName("numLabel");
                numLabel.text = info.num + '';
                switch (info.type) {
                    case rewardResType.coin:
                        icon.skin = "assets_dialog/coin_icon.png";
                        break;
                    case rewardResType.statu:
                        icon.skin = "assets_dialog/status_icon.png";
                        break;
                    case rewardResType.energy:
                        icon.skin = "assets_dialog/活跃度02.png";
                        break;
                }
            }
        }
        _initView() {
            this._config = DailyTaskManager.Instance.getSortDailyListConfig();
            this._updateEnergy();
            this.taskList.vScrollBarSkin = "";
            this.taskList.array = this._config;
            this.taskList.renderHandler = Laya.Handler.create(this, this._render, null, false);
        }
        closeView() {
            UIMng.instance.closeUIScene(UIScene.dailyTask);
        }
    }

