    class KeJuManager {
        constructor() {
            this.isplayingKeju = false;
            this._gameIDList = [];
            this._get_answer = 0;
            this._gameIndex = 0;
            this._gameTime = 0;
            this._addTime = 0;
        }
        static get instance() {
            if (KeJuManager._instance == null)
                KeJuManager._instance = new KeJuManager();
            return KeJuManager._instance;
        }
        set GameIDList(value) {
            this._gameIDList = value;
        }
        get GameIDList() {
            return this._gameIDList;
        }
        get_aswser() {
            this._get_answer++;
        }
        get get_answer() {
            return this._get_answer;
        }
        get GameIndex() {
            return this._gameIndex;
        }
        updateGameIndex() {
            this._gameIndex++;
            this._get_answer = 0;
            if (this._gameIndex >= this._gameIDList.length) {
                return true;
            }
            return false;
        }
        getGameInfo(index = this._gameIndex) {
            return this._gameIDList[index];
        }
        getRandomGameList(num = 3) {
            this._gameIDList = Util.getRandomArrElement2(KeJuConfig.gameListConfig, num);
            KeJuConfig.gameTime = 0;
            for (const key in this._gameIDList) {
                if (Object.prototype.hasOwnProperty.call(this._gameIDList, key)) {
                    const info = this._gameIDList[key];
                    if (info) {
                        KeJuConfig.gameTime += info.time ? info.time : 0;
                    }
                }
            }
            console.error("------this._gameIDList", this._gameIDList);
        }
        updateGameTime(timeOff) {
            this._gameTime += timeOff;
        }
        get GameTime() {
            return this._gameTime;
        }
        get addTime() {
            return this._addTime;
        }
        updateAddTime(time) {
            this._addTime += time;
        }
        reset() {
            this._gameIDList = [];
            this._gameIndex = 0;
            this._gameTime = 0;
            this._addTime = 0;
        }
        get TotalTime() {
            let time = KeJuConfig.gameTime + this._addTime - this._gameTime / 1000;
            if (time < 0)
                time = 0;
            return time;
        }
        init() {}
        initAddword() {
            return new Promise((resolve, reject) => __awaiter(this, void 0, void 0, function* () {
                if (!this._addword_config) {
                    this._addword_config = yield ConfigManager.instance.loadConfig("keju_addword");
                }
                resolve(this._addword_config);
            }));
        }
    }
    KeJuManager._instance = null;

