    class DayLoginDialogUI extends ui.ui_dialog.DayLoginDialogUI {
        constructor() {
            super(...arguments);
            this._btnLock = false;
            this._info = null;
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.sign_mod);
            this._initView();
        }
        onEnable() {
            L3D.onclick(this.bg, this, this._bgClick);
            L3D.onclick(this.closeBtn, this, this._closeBtnClick);
            L3D.onclick(this.btnGet, this, this._getBtnClick);
            L3D.onclick(this.btnVideo, this, this._btnVideoBtnClick);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this._bgClick);
            L3D.offclick(this.closeBtn, this, this._closeBtnClick);
            L3D.offclick(this.btnGet, this, this._getBtnClick);
            L3D.offclick(this.btnVideo, this, this._btnVideoBtnClick);
        }
        _bgClick() {
            if (this._btnLock)
                return;
            this.closeView();
        }
        _closeBtnClick() {
            if (this._btnLock)
                return;
            this.closeView();
        }
        _getBtnClick() {
            if (this._btnLock)
                return;
            StorageManager.instance.isVideoDayLogin = true;
            this._getReward();
            this._updateDayLoginInfo();
        }
        _btnVideoBtnClick() {
            if (this._btnLock)
                return;
            this._btnLock = true;
            SDKManager.instance.ShareOrVideo(ShareLoc.signup, () => {
                this._btnLock = false;
                StorageManager.instance.dayLoginVideoTwice++;
                if (this._info && this._info.videoTwice <= StorageManager.instance.dayLoginVideoTwice) {
                    StorageManager.instance.dayLoginVideoTwice = 0;
                    this._getReward();
                    this._updateDayLoginInfo();
                } else {
                    StorageManager.instance.syncData();
                }
                this._setVideoTip();
            }, () => {
                this._btnLock = false;
            });
        }
        _getReward() {
            StorageManager.instance.dayLoginRewardTiwce++;
            let tip = DayLoginManager.Instance.sendReward(StorageManager.instance.dayLoginRewardTiwce);
            if (tip) {
                UIMng.instance.createMultLineTips(tip);
            } else {
                console.log("===没有描述");
            }
            ModuleReportManager.inst.updateStorage(ModuleReportName.sign_mod, StorageManager.instance.dayLoginRewardTiwce);
            GameEvent.ev(GameEV.updateRedTip);
            StorageManager.instance.syncData();
        }
        _initView() {
            this._updateDayLoginInfo();
        }
        _showCommonGet() {
            this.btnGet.visible = true;
            this.btnVideo.visible = false;
            this.dayLabel.visible = false;
            this.get_Anim.play(0, true);
        }
        _showVideoGet() {
            this.btnGet.visible = false;
            this.btnVideo.visible = true;
            this.dayLabel.visible = true;
            this.video_Anim.play(0, true);
            this._setVideoTip();
        }
        _setVideoTip() {
            let videoTwice = StorageManager.instance.dayLoginVideoTwice;
            this.twiceLabel.text = videoTwice + '';
            this.dayLabel.text = "提前领取第" + (StorageManager.instance.dayLoginRewardTiwce + 1) + "天奖励，还需观看";
            this.targetLabel.text = "/" + this._info.videoTwice + "次视频";
        }
        _updateDayLoginInfo(twice = StorageManager.instance.dayLoginRewardTiwce + 1) {
            this.light.visible = false;
            let len = DayLoginManager.Instance.loginDayConfig;
            for (let i = 0; i < len; i++) {
                let day = i + 1;
                let child = this.list.getChildByName("listItem" + day);
                if (child) {
                    let state = 1;
                    if (i > StorageManager.instance.dayLoginRewardTiwce) {
                        state = 1;
                    } else if (i == StorageManager.instance.dayLoginRewardTiwce) {
                        state = 2;
                        this.light.visible = true;
                        this.light.width = child.width + 30;
                        this.light.height = child.height + 30;
                        this.light.pos(child.x - 14, child.y - 14);
                    } else {
                        state = 3;
                    }
                    this._setListItemState(child, state);
                }
            }
            let info = DayLoginManager.Instance.getRwardInfo(twice);
            if (!info) {
                this.btnGet.visible = false;
                this.btnVideo.visible = false;
                this.dayLabel.visible = false;
            } else {
                this._info = info;
                if (StorageManager.instance.isVideoDayLogin) {
                    this._showVideoGet();
                } else {
                    this._showCommonGet();
                }
            }
        }
        _setListItemState(item, state) {
            if (item) {
                let hasGet = item.getChildByName("hasGet");
                if (state == 3) {
                    hasGet && (hasGet.visible = true);
                } else {
                    hasGet && (hasGet.visible = false);
                }
            }
        }
        closeView() {
            UIMng.instance.closeUIScene(UIScene.dayLogin);
        }
    }

    class EffectButton extends Laya.Script {
        constructor() {
            super(...arguments);
            this._scale = 0.85;
            this._musicUrl = "btn.mp3";
            this._color = 0xffffff;
            this._buttonDown = false;
        }
        onAwake() {
            Laya.timer.frameOnce(1, this, () => {
                this._root = this.owner;
                this._root.on(Laya.Event.MOUSE_DOWN, this, this.onTouchIt);
                this._root.on(Laya.Event.MOUSE_UP, this, this.onTouchEnd);
                this._root.on(Laya.Event.MOUSE_OUT, this, this.onTouchEnd);
                this._root.on(Laya.Event.CLICK, this, this.onTouchEnd);
                if (this._root.pivotX == 0 && this._root.pivotY == 0) {
                    this._root.pivot(this._root.width / 2, this._root.height / 2);
                    this._root.pos(this._root.x + this._root.width / 2, this._root.y + this._root.height / 2);
                }
                this._originalScaleX = this._root.scaleX;
                this._originalScaleY = this._root.scaleY;
            });
        }
        get musicUrl() {
            return this._musicUrl;
        }
        set musicUrl(url) {
            this._musicUrl = url;
        }
        get color() {
            return this._color;
        }
        set color(value) {
            let b = value % 256;
            let g = Math.floor((value / 256) % 256);
            let r = Math.floor(value / 256 / 256);
            let colorMatrix = [r / 255, 0, 0, 0, 0, 0, g / 255, 0, 0, 0, 0, 0, b / 255, 0, 0, 0, 0, 0, 1, 0];
        }
        onTouchIt() {
            if (!this._buttonDown) {
                Laya.Tween.to(this._root, {
                    scaleX: this._originalScaleX * this._scale,
                    scaleY: this._originalScaleY * this._scale,
                    rotation: 0
                }, 180, Laya.Ease.elasticOut);
                AudioManager.instance.playSound("click.OGG");
                this._buttonDown = true;
            }
        }
        onTouchEnd() {
            if (this._buttonDown) {
                Laya.Tween.to(this._root, {
                    scaleX: this._originalScaleX,
                    scaleY: this._originalScaleY
                }, 196, Laya.Ease.sineOut);
                this._buttonDown = false;
            }
        }
    }

