    class DigGiftExchangeUI extends ui.ui_dialog.DigGiftExchangeUI {
        constructor() {
            super(...arguments);
            this._is_click_exchange = false;
        }
        onAwake() {
            this.btnExchange.on(Laya.Event.CLICK, this, this._on_exchange);
            this.bg.on(Laya.Event.CLICK, this, this._on_close);
            this.btn_close.on(Laya.Event.CLICK, this, this._on_close);
        }
        _on_close() {
            UIMng.instance.closeUIScene(UIScene.DigGiftExchange);
        }
        _on_exchange() {
            if (this._is_click_exchange)
                return;
            this._is_click_exchange = true;
            let code = this.text_input.text;
            if (code == ``) {
                UIMng.instance.createTips("请输入兑换码");
                this._is_click_exchange = false;
                return;
            }
            let suc = (gift) => {
                if (gift) {
                    UIMng.instance.createTips(gift.description);
                    let reward_dict = JSON.parse(gift.content_code);
                    console.log(`JSON.parse(gift.content_code)::`, JSON.parse(gift.content_code));
                    for (let key in reward_dict) {
                        let value = 0;
                        if (typeof (parseInt(reward_dict[key])) == "number") {
                            value = Math.floor(parseInt(reward_dict[key]));
                        }
                        if (this[`_${key}`]) {
                            this[`_${key}`](value);
                        }
                        console.log(`key::`, key, `reward_dict[key]:`, reward_dict[key], `value::`, value);
                    }
                } else {
                    UIMng.instance.createTips("兑换码无效");
                }
                this._on_close();
            };
            let fail = (m) => {
                if (m) {
                    UIMng.instance.createTips(m);
                } else {
                    UIMng.instance.createTips("兑换码无效");
                }
                this._on_close();
            };
            SDKManager.instance.getExchange(code, suc, fail);
        }
        _addCoinValue(v) {
            if (!v)
                return;
            console.log(`_addCoinValue::`, v);
            v = Math.floor(v);
            StorageManager.instance.Coin += v;
        }
        _addRewardSocialStatus(v) {
            if (!v)
                return;
            console.log(`_addRewardSocialStatus::`, v);
            StorageManager.instance.addRewardSocialStatus(v);
        }
        _addYuXi(v) {
            if (!v)
                return;
            console.log(`_addYuXi::`, v);
            StorageManager.instance.YuXi += v;
        }
    }

