    class myMath {
        static NumberFormat(coin) {
            coin = Math.floor(coin);
            let strTemp = coin.toString();
            let index = strTemp.indexOf('e+');
            if (index != -1) {
                let str1 = strTemp.slice(0, index);
                let str2 = strTemp.slice(index + 2);
                let len = Number(str2);
                let a = str1.indexOf('.');
                str2 = str1.slice(a + 1);
                str1 = str1.slice(0, a);
                let len2 = len - str2.length;
                strTemp = `${str1}${str2}`;
                for (let i = 0; i < len2; i++) {
                    strTemp += '0';
                }
            }
            let result;
            if (strTemp.length > 3) {
                let unitArr = ['K', 'M', 'B', "T", 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
                let unit = Math.floor((strTemp.length - 4) / 3);
                let big = (coin / (Math.pow(1000, unit))).toFixed(0);
                if (big.length > 3) {
                    result = big.substring(0, big.length - 3) + '.' + big.substring(big.length - 3, big.length - 2) + unitArr[unit];
                } else {
                    result = big + unitArr[unit];
                }
            } else {
                if (coin.toString().length > 3) {
                    let temp = coin.toString();
                    result = temp.substring(0, temp.length - 3) + '.' + temp.substring(temp.length - 3, temp.length);
                } else {
                    result = coin;
                }
            }
            return result;
        }
        static NumberFormat2(coin) {
            coin = Math.floor(coin);
            let strTemp = coin.toString();
            let index = strTemp.indexOf('e+');
            if (index != -1) {
                let str1 = strTemp.slice(0, index);
                let str2 = strTemp.slice(index + 2);
                let len = Number(str2);
                let a = str1.indexOf('.');
                str2 = str1.slice(a + 1);
                str1 = str1.slice(0, a);
                let len2 = len - str2.length;
                strTemp = `${str1}${str2}`;
                for (let i = 0; i < len2; i++) {
                    strTemp += '0';
                }
            }
            let result;
            if (strTemp.length > 3) {
                let unitArr = ['K', 'M', 'B', "T", 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
                let unit = Math.floor((strTemp.length - 4) / 3);
                let big = (coin / (Math.pow(1000, unit))).toFixed(0);
                if (big.length > 3) {
                    result = big.substring(0, big.length - 3) + '_' + big.substring(big.length - 3, big.length - 2) + unitArr[unit];
                } else {
                    result = big + unitArr[unit];
                }
            } else {
                if (coin.toString().length > 3) {
                    let temp = coin.toString();
                    result = temp.substring(0, temp.length - 3) + '_' + temp.substring(temp.length - 3, temp.length);
                } else {
                    result = coin;
                }
            }
            return result;
        }
        static TimeFormat(num = 0) {
            let min = Math.floor(num / 60);
            let hour = Math.floor(min / 60);
            let day = Math.floor(hour / 24);
            let s = Math.floor(num % 60);
            if (day == 0) {
                if (hour == 0) {
                    if (min == 0) {
                        if (s <= 9) {
                            return `${min}:0${s}`;
                        }
                        return `${min}:${s}`;
                    }
                    if (s <= 9) {
                        return `${min}:0${s}`;
                    }
                    return `${min}:${s}`;
                } else {
                    return `${hour}:${min}:${s}`;
                }
            } else {
                return `${day}:${hour}:${min}:${s}`;
            }
        }
        static TimerFormat(num = 0) {
            let hour = Math.floor(num / 3600);
            let minute = Math.floor((num % 3600) / 60);
            let second = Math.floor((num % 3600) % 60);
            if (hour <= 9)
                hour = '0' + hour;
            if (minute <= 9)
                minute = '0' + minute;
            if (second <= 9)
                second = '0' + second;
            return `${hour}:${minute}:${second}`;
        }
        static TimerFormat_min_second(num = 0) {
            let minute = Math.floor(num / 60);
            let second = Math.floor((num % 3600) % 60);
            if (minute <= 9)
                minute = '0' + minute;
            if (second <= 9)
                second = '0' + second;
            return `${minute}:${second}`;
        }
        static ContrastDay(time1, time2) {
            let signDate = new Date(time1);
            let now = new Date(time2);
            if (now.getFullYear() != signDate.getFullYear() || now.getMonth() != signDate.getMonth() || now.getDate() != signDate.getDate()) {
                return false;
            } else {
                return true;
            }
        }
        static MahtSin(sideA, sideC) {
            return 180 / Math.PI * Math.asin(sideA / sideC);
        }
        static GetRandom(Min, Max) {
            var Range = Max - Min;
            var Rand = Math.random();
            return (Min + Math.round(Rand * Range));
        }
        static removeByValue(arr, val) {
            var i = arr.indexOf(val);
            if (i >= 0) {
                arr.splice(i, 1);
            }
        }
        static removeFromAaary(arr1, arr2, arr1_length) {
            function removeNode() {
                for (var i = 0; i < arr1.length; i++) {
                    for (var j = 0; j < arr2.length; j++) {
                        if (arr1[i] == arr2[j]) {
                            arr1.splice(i, 1);
                            return;
                        }
                    }
                }
            }
            for (var k = 0; k < arr1_length; k++) {
                removeNode();
            }
            return arr1;
        }
        static randomsort(a, b) {
            return Math.random() > .5 ? -1 : 1;
        }
        static RandomInt(min, max) {
            let length = max - min;
            return Math.floor(Math.random() * length + min);
        }
        static shuffle(arr) {
            let i = arr.length;
            let _arr = [];
            arr.forEach((val) => {
                _arr.push(val);
            });
            while (i) {
                let j = Math.floor(Math.random() * i--);
                [_arr[j], _arr[i]] = [_arr[i], _arr[j]];
            }
            return _arr;
        }
        static getRandomArr(arr, num) {
            let _arr = [];
            arr.forEach((val) => {
                _arr.push(val);
            });
            let arrOut = [];
            for (let i = 0; i < num; i++) {
                let len = _arr.length;
                let ran = Math.floor(Math.random() * len);
                arrOut[i] = _arr.splice(ran, 1)[0];
            }
            return arrOut;
        }
        static getRandomArr_splic(arr, num) {
            let _list = [...arr];
            let arrOut = [];
            for (let i = 0; i < num; i++) {
                let len = _list.length;
                let random = Math.floor(Math.random() * len);
                arrOut[i] = _list.splice(random, 1)[0];
            }
            return arrOut;
        }
        static getArrRandNum(arr, nums) {
            let get_rand_list = [];
            let index_list = [];
            for (let i = 0; i < arr.length; i++) {
                index_list.push(i);
            }
            for (let i = 0; i < nums && i < index_list.length; i++) {
                let index = index_list[myMath.RandomInt(0, index_list.length)];
                get_rand_list.push(arr[index]);
                index_list = index_list.filter((v) => {
                    return v != index;
                });
            }
            if (nums > arr.length) {
                let out_num = nums - arr.length;
                for (let i = 0; i < out_num; i++) {
                    let rand_item = arr[myMath.RandomInt(0, arr.length)];
                    get_rand_list.push(rand_item);
                }
            }
            return get_rand_list;
        }
        static RandomWeight(weight_item) {
            let data = {};
            weight_item.forEach((item) => {
                data[item.key] = item.weight;
            });
            let get_key = this.RandomWeight3(data);
            return get_key;
        }
        static RandomWeight3(weigthArr) {
            let items = [];
            let weigths = [];
            let weightMax = 0;
            for (let k in weigthArr) {
                items.push(k);
                let value = weigthArr[k];
                weigths.push(value);
                weightMax += value;
            }
            weightMax = Math.floor(weightMax);
            let rand = Math.floor(Math.random() * weightMax);
            let searchValueSum = 0;
            for (let i = 0; i < items.length; i++) {
                searchValueSum += weigths[i];
                if (rand <= searchValueSum) {
                    let key = items[i];
                    return key;
                }
            }
            return null;
        }
        static RandomWeight4(weightObj) {
            let items = [];
            let weigths = [];
            let weightMax = 0;
            for (let k in weightObj) {
                items.push(k);
                let value = weightObj[k].weight;
                weigths.push(value);
                weightMax += value;
            }
            weightMax = Math.floor(weightMax);
            let rand = Math.floor(Math.random() * weightMax);
            let searchValueSum = 0;
            for (let i = 0; i < items.length; i++) {
                searchValueSum += weigths[i];
                if (rand <= searchValueSum) {
                    let key = items[i];
                    let item = weightObj[key];
                    return item;
                }
            }
            return null;
        }
        static compare(property) {
            return function (a, b) {
                let value1 = a[property];
                let value2 = b[property];
                return value2 - value1;
            };
        }
        static getTime(date_str) {
            let timestrip = new Date(date_str);
            if (Number.isNaN(timestrip.getTime()))
                timestrip = new Date(date_str.replace(/-/g, '/'));
            return timestrip;
        }
        static getWeekStartDate() {
            let now = new Date();
            let nowDayOfWeek = now.getDay();
            let nowDay = now.getDate();
            let nowMonth = now.getMonth();
            let nowYear = now.getFullYear();
            let weekStartDate = new Date(nowYear, nowMonth, nowDay - nowDayOfWeek + 1);
            return myMath.formatDate(weekStartDate);
        }
        static getWeekEndDate() {
            let now = new Date();
            let nowDayOfWeek = now.getDay();
            let nowDay = now.getDate();
            let nowMonth = now.getMonth();
            let nowYear = now.getFullYear();
            let weekEndDate = new Date(nowYear, nowMonth, nowDay + (7 - nowDayOfWeek));
            return myMath.formatDate(weekEndDate);
        }
        static formatDateTime(inputTime, type) {
            let date = new Date(inputTime);
            let y = date.getFullYear();
            let m = date.getMonth() + 1;
            m = m < 10 ? ('0' + m) : m;
            let d = date.getDate();
            d = d < 10 ? ('0' + d) : d;
            let h = date.getHours();
            h = h < 10 ? ('0' + h) : h;
            let minute = date.getMinutes();
            let second = date.getSeconds();
            minute = minute < 10 ? ('0' + minute) : minute;
            second = second < 10 ? ('0' + second) : second;
            if (type) {
                return y + '-' + m + '-' + d + ' ' + h + ':' + minute + ':' + second;
            } else {
                return y + '-' + m + '-' + d;
            }
        }
        static formatDate(date) {
            let myyear = date.getFullYear();
            let mymonth = date.getMonth() + 1;
            let myweekday = date.getDate();
            if (mymonth < 10) {
                mymonth = "0" + mymonth;
            }
            if (myweekday < 10) {
                myweekday = "0" + myweekday;
            }
            return (myyear + "-" + mymonth + "-" + myweekday);
        }
        static angleToRad(angle) {
            return Math.PI / 180 * angle;
        }
        static radToAngle(rad) {
            return 180 / Math.PI * rad;
        }
        static Clamp(value, min, max) {
            if (value < min) {
                return min;
            } else {
                return value > max ? max : value;
            }
        }
        static getAngle1(v1, v2) {
            let m1 = Math.sqrt(v1.x * v1.x + v1.y * v1.y + v1.z * v1.z);
            let m2 = Math.sqrt(Math.pow(v2.x, 2) + Math.pow(v2.y, 2) + Math.pow(v2.z, 2));
            let mul_v = v1.x * v2.x + v1.y * v2.y + v1.z * v2.z;
            let cosM = mul_v / (m1 * m2);
            let angle = Math.acos(cosM) * 180 / Math.PI;
            return angle;
        }
    }

    class GuideManager {
        constructor() {
            this._guideindex = 0;
            this._config = [];
            this._config_shit = [];
        }
        static get instance() {
            if (GuideManager._instance == null)
                GuideManager._instance = new GuideManager();
            return GuideManager._instance;
        }
        set GuideIndex(val) {
            this._guideindex = val;
            GameEvent.ev(GameEV.refreshGuide);
        }
        get GuideIndex() {
            return this._guideindex;
        }
        get Config() {
            if (GC.gm.sceneTag == SceneTag.mainGame) {
                return this._config;
            } else {
                return this._config_shit;
            }
        }
        init() {
            return __awaiter(this, void 0, void 0, function* () {
                this._config = yield ConfigManager.instance.loadConfig("guide_config");
                this._config_shit = yield ConfigManager.instance.loadConfig("guide_config_shit");
            });
        }
        isNew() {
            if (GC.gm.sceneTag == SceneTag.mainGame) {
                return StorageManager.instance.CollectCoin <= 0;
            } else {
                return false;
            }
        }
        nextStep(delay) {
            this._guideindex++;
            GameEvent.ev(GameEV.refreshGuide, delay);
        }
        getConfigByIndex(index) {
            if (GC.gm.sceneTag == SceneTag.mainGame) {
                return this._config[index];
            } else {
                return this._config_shit[index];
            }
        }
        getCurrentConfig() {
            if (GC.gm.sceneTag == SceneTag.mainGame) {
                return this._config[this._guideindex];
            } else {
                return this._config_shit[this._guideindex];
            }
        }
        GuideOver() {
            this._guideindex = 0;
            if (GC.gm.sceneTag == SceneTag.mainGame) {
                if (GC.gm.currentSceneCtrl)
                    GC.gm.currentSceneCtrl.guideover();
            } else {
                StorageManager.instance.shitGuided = true;
            }
        }
    }
