        _refresh_order_list() {
            let order_list = [];
            if (!StorageManager.instance.compose_order_list.length) {
                order_list = [1];
            } else {
                let all_order = [1];
                for (let i = 0; i < StorageManager.instance.compose_order_list.length; i++) {
                    let index = StorageManager.instance.compose_order_list[i] - 1;
                    let item_config = this._order_config[index];
                    all_order = all_order.concat(item_config.rely_on);
                }
                order_list = all_order.filter((value) => {
                    return !StorageManager.instance.compose_order_list.includes(value);
                });
            }
            this._order_list = order_list;
        }
        get_order_list() {
            if (!StorageManager.instance.guideScene3Complete && GuideScene3Manager.instance.GuideIndex < 36)
                return [];
            else if (GuideScene3Manager.instance.GuideIndex == 37)
                return [1];
            else if (GuideScene3Manager.instance.GuideIndex > 37 && GuideScene3Manager.instance.GuideIndex < 42)
                return [];
            else if (GuideScene3Manager.instance.GuideIndex == 42)
                return [2];
            return this._order_list.concat();
        }
        if_order_can_complete(order) {
            let order_config = this._order_config[order - 1];
            let storage_data = {};
            for (let i = 0; i < StorageManager.instance.grid_id.length; i++) {
                if (this.getGridUnlock(i) == 0) {
                    let id = this.getGridID(i);
                    if (!storage_data[id])
                        storage_data[id] = 0;
                    storage_data[id]++;
                }
            }
            let complete_num = 0;
            for (let i = 0; i < order_config.propid.length; i++) {
                let propid = order_config.propid[i].propid;
                let num = order_config.propid[i].propnum;
                if (storage_data[propid] >= num)
                    complete_num++;
            }
            if (complete_num >= order_config.propid.length)
                return true;
            return false;
        }
        order_complete(order) {
            let order_item = this._order_config[order - 1];
            if (!StorageManager.instance.compose_order_list.includes(order)) {
                StorageManager.instance.compose_order_list.push(order);
                StorageManager.instance.sync_compose_storage();
            }
            let clean_prop_id = [];
            order_item.propid.forEach((v) => {
                for (let i = 0; i < v.propnum; i++) {
                    clean_prop_id.push(v.propid);
                }
            });
            if (clean_prop_id.length == 1) {
                let clean_id = clean_prop_id[0];
                for (let g = 0; g < StorageManager.instance.grid_id.length; g++) {
                    let grid_id = StorageManager.instance.grid_id[g];
                    if (grid_id == clean_id && StorageManager.instance.grid_unlock[g] == 0) {
                        this.clean_grid_storage(g);
                        break;
                    }
                }
            } else {
                for (let i = 0; i < clean_prop_id.length; i++) {
                    let clean_id = clean_prop_id[i];
                    for (let g = 0; g < StorageManager.instance.grid_id.length; g++) {
                        let grid_id = StorageManager.instance.grid_id[g];
                        if (grid_id == clean_id && StorageManager.instance.grid_unlock[g] == 0) {
                            this.clean_grid_storage(g);
                            break;
                        }
                    }
                }
            }
            if (StorageManager.instance.com_guide_step < this._guide_step_sum) {
                let get_step = 0;
                for (let key in this._guide_config) {
                    if (this._guide_config[key].order_id && this._guide_config[key].order_id == order) {
                        get_step = this._guide_config[key].step;
                        break;
                    }
                }
                if (get_step) {
                    StorageManager.instance.com_guide_step = get_step;
                    this._to_complete_guide();
                }
            }
            this._refresh_order_list();
            GameEvent.ev(GameEV.orderRefresh, order);
            if (order == 2) {
                StorageManager.instance.sync_compose_storage(true);
            }
            if (GuideScene3Manager.instance.GuideIndex == 37 || GuideScene3Manager.instance.GuideIndex == 42) {
                GameEvent.ev(GameEV.refreshGuide);
            }
        }
        order_get_award(order) {
            let order_item = this._order_config[order - 1];
            StorageManager.instance.Coin += order_item.reward;
            if (order_item.rewardprop != 0) {
                this.push_into_temp_box(order_item.rewardprop);
            }
        }
        is_order_need_prop_id(id) {
            let order_list = this.get_order_list();
            let need_ids = [];
            for (let i = 0; i < order_list.length; i++) {
                let order = order_list[i];
                this._order_config[order - 1].propid.forEach((v) => {
                    need_ids.push(v.propid);
                });
            }
            return need_ids.includes(id);
        }
        is_have_order_can_complete() {
            let complete_order = 0;
            let storage_ids_num = {};
            for (let i = 0; i < StorageManager.instance.grid_id.length; i++) {
                if (StorageManager.instance.grid_unlock[i] == 0) {
                    let id = StorageManager.instance.grid_id[i];
                    if (!storage_ids_num[id])
                        storage_ids_num[id] = 0;
                    storage_ids_num[id]++;
                }
            }
            let order_list = this.get_order_list();
            let mission_order = this.compare_order_id_by_mission();
            if (mission_order)
                order_list = [mission_order].concat(order_list);
            if (!order_list.length) {
                complete_order = 0;
            }
            for (let i = 0; i < order_list.length; i++) {
                let order = order_list[i];
                let order_config = this._order_config[order - 1];
                let needs = order_config.propid;
                let is_complete_id_num = 0;
                for (let n = 0; n < needs.length; n++) {
                    let need_id = needs[n].propid;
                    if (storage_ids_num[need_id] >= needs[n].propnum) {
                        is_complete_id_num++;
                    }
                }
                if (is_complete_id_num >= needs.length) {
                    complete_order = order;
                    break;
                }
            }
            return complete_order;
        }
        compare_order_id_by_mission() {
            let order_list = this.get_order_list();
            let mission = MissionManager.instance.getCurrentMission();
            if (!mission || !mission.guidearea)
                return 0;
            let mission_order_id = 0;
            let mission_guide = mission.guidearea.substring(0, 2);
            if (mission_guide == "ur" || mission_guide == "ug") {
                let mission_area = mission.guidearea.substring(3);
                for (let i = 0; i < order_list.length; i++) {
                    let order_id = order_list[i];
                    let order_config = ComposeManaget.inst.order_config[order_id - 1];
                    if (order_config.arealevel.includes(mission_area)) {
                        if (mission_guide == "ur" && order_config.arealevel[0] == "r") {
                            mission_order_id = order_id;
                            break;
                        } else if (mission_guide == "ug" && order_config.arealevel[0] == "g") {
                            mission_order_id = order_id;
                            break;
                        }
                    }
                }
            }
            return mission_order_id;
        }
