                [SceneTag.mainGame2]: [100, 500, 1000, 1500, 2500, 3500, 5500, 7500, 9500, 12500, 15000, 18000],
                [SceneTag.mainGame3]: [1000, 1500, 3000, 4500, 6000, 7500, 8000, 9500, 11500, 14000, 16500, 19000, 21500, 25500, 29500, 32500, 38500, 45000],
