    class GoBangGameManager {
        constructor() {
            this.roundTime = 30000;
            this.difficultLevelInfo = {
                1: [10000, 30000, 60000, 90000],
                2: [100, 100, 100, 600, 600, 600, 5000, 5000, 5000],
                3: [0],
            };
            this.chessman_originPos = new Laya.Vector2(5, 6);
            this.chessman_OffPos = new Laya.Vector2(48, 47);
            this.chessman_count = 15;
            this.chessboard_OffPos = new Laya.Vector2(27.5, 25.5);
            this.chessBoardInfo = [];
            this.winsAllIndexInfo = [];
            this.win_player = [];
            this.fail_player = [];
            this.win_ai = [];
            this.fail_ai = [];
            this.curChessmanType = ChessmanType.white;
            this.selfChessmanType = ChessmanType.white;
            this.aiChessmanType = ChessmanType.black;
            this.selfPlayer = null;
            this.aiPlayer = null;
            this._gameState = GoBangGameState.none;
            this.chessBoardRecord = [];
        }
        static get instance() {
            if (!GoBangGameManager._instance)
                GoBangGameManager._instance = new GoBangGameManager();
            return GoBangGameManager._instance;
        }
        getDifficultRandomValue(level) {
            let info = this.difficultLevelInfo[level];
            if (info) {
                let index = Util.RandomInt(0, info.length);
                return info[index];
            }
            return Math.random() * 300;
        }
        get diffculty() {
            if (StorageManager.instance.chessmanWinTiwce < 1) {
                return 1;
            } else if (StorageManager.instance.chessmanWinTiwce < 2 &&
                StorageManager.instance.chessmanWinTiwce >= 1) {
                return 2;
            } else {
                return 3;
            }
        };
        set GameState(state) {
            this._gameState = state;
        }
        get GameState() {
            return this._gameState;
        }
        initManager() {
            this.chessBoardRecord = [];
            this.winsAllInfo = [];
            this.winsAllIndexInfo = [];
            this.win_player = [];
            this.fail_player = [];
            this.win_ai = [];
            this.fail_ai = [];
            this.chessBoardInfo = [];
            for (let i = 0; i < this.chessman_count; i++) {
                this.chessBoardInfo[i] = [];
                for (let j = 0; j < this.chessman_count; j++) {
                    this.chessBoardInfo[i].push({
                        gridType: 0,
                        girdCtrl: null
                    });
                }
            }
            this.statistics_win();
        }
        resetManager() {
            this.chessBoardInfo = null;
            this.winsAllNum = 0;
            this.winsAllInfo = null;
            this.winsAllIndexInfo = null;
            this.win_ai = null;
            this.fail_ai = null;
            this.win_player = null;
            this.fail_player = null;
            this.selfPlayer = null;
            this.aiPlayer = null;
            this.chessBoardRecord = null;
        }
        statistics_win() {
            for (var i = 0; i < this.chessman_count; i++) {
                this.winsAllInfo[i] = [];
                for (var j = 0; j < this.chessman_count; j++) {
                    this.winsAllInfo[i][j] = [];
                }
            }
            this.winsAllNum = 0;
            for (var i = 0; i < 15; i++) {
                for (var j = 0; j < 11; j++) {
                    for (var k = 0; k < 5; k++) {
                        this.winsAllInfo[i][j + k][this.winsAllNum] = true;
                        if (!this.winsAllIndexInfo[this.winsAllNum]) {
                            this.winsAllIndexInfo[this.winsAllNum] = [];
                        }
                        this.winsAllIndexInfo[this.winsAllNum].push([i, j + k]);
                    }
                    this.winsAllNum++;
                }
            }
            for (var i = 0; i < 15; i++) {
                for (var j = 0; j < 11; j++) {
                    for (var k = 0; k < 5; k++) {
                        this.winsAllInfo[j + k][i][this.winsAllNum] = true;
                        if (!this.winsAllIndexInfo[this.winsAllNum]) {
                            this.winsAllIndexInfo[this.winsAllNum] = [];
                        }
                        this.winsAllIndexInfo[this.winsAllNum].push([j + k, i]);
                    }
                    this.winsAllNum++;
                }
            }
            for (var i = 0; i < 11; i++) {
                for (var j = 0; j < 11; j++) {
                    for (var k = 0; k < 5; k++) {
                        this.winsAllInfo[i + k][j + k][this.winsAllNum] = true;
                        if (!this.winsAllIndexInfo[this.winsAllNum]) {
                            this.winsAllIndexInfo[this.winsAllNum] = [];
                        }
                        this.winsAllIndexInfo[this.winsAllNum].push([i + k, j + k]);
                    }
                    this.winsAllNum++;
                }
            }
            for (var i = 0; i < 11; i++) {
                for (var j = 14; j > 3; j--) {
                    for (var k = 0; k < 5; k++) {
                        this.winsAllInfo[i + k][j - k][this.winsAllNum] = true;
                        if (!this.winsAllIndexInfo[this.winsAllNum]) {
                            this.winsAllIndexInfo[this.winsAllNum] = [];
                        }
                        this.winsAllIndexInfo[this.winsAllNum].push([i + k, j - k]);
                    }
                    this.winsAllNum++;
                }
            }
            for (var i = 0; i < this.winsAllNum; i++) {
                this.win_player[i] = 0;
                this.fail_player[i] = 0;
                this.win_ai[i] = 0;
                this.fail_ai[i] = 0;
            }
        }
        getIndexByValue(value, interval, maxIndex) {
            let index = 0;
            index = Math.round(value / interval);
            if (index >= maxIndex) {
                index = maxIndex - 1;
            }
            if (index <= 0) {
                index = 0;
            }
            return index;
        }
        updateChessmanType(curType) {
            this.curChessmanType = (curType == this.selfChessmanType ? this.aiChessmanType : this.selfChessmanType);
        }
        getchessImageUrl(curType) {
            let url = '';
            if (curType == ChessmanType.black) {
                url = "assets_goBang/黑子01.png";
            } else if (curType == ChessmanType.white) {
                url = "assets_goBang/白子01.png";
            }
            return url;
        }
        getCombo(index, type) {
            let v_combo = 1;
            let y = index.y;
            let x = index.x;
            let top = y - 5 >= 0 ? y - 5 : 0;
            for (let i = y - 1; i > top; i--) {
                let info = this.chessBoardInfo[x][i];
                if (info && info.gridType == type) {
                    v_combo += 1;
                } else {
                    break;
                }
            }
            let bottom = y + 5 >= this.chessman_count ? this.chessman_count - 1 : y + 5;
            for (let i = y + 1; i < bottom; i++) {
                let info = this.chessBoardInfo[x][i];
                if (info && info.gridType == type) {
                    v_combo += 1;
                } else {
                    break;
                }
            }
            let h_combo = 1;
            let left = index.x - 5 >= 0 ? index.x - 5 : 0;
            for (let i = x - 1; i > left; i--) {
                let info = this.chessBoardInfo[i][y];
                if (info && info.gridType == type) {
                    h_combo += 1;
                } else {
                    break;
                }
            }
            let right = x + 5 >= this.chessman_count ? this.chessman_count - 1 : x + 5;
            for (let i = x + 1; i < right; i++) {
                let info = this.chessBoardInfo[i][y];
                if (info && info.gridType == type) {
                    h_combo += 1;
                } else {
                    break;
                }
            }
            let vh_combo = 1;
            for (let i = 1; i < 5; i++) {
                let new_x = x + i;
                let new_y = y + i;
                if (new_x < this.chessman_count &&
                    new_y < this.chessman_count &&
                    new_x >= 0 &&
                    new_y >= 0) {
                    let info = this.chessBoardInfo[new_x][new_y];
                    if (info && info.gridType == type) {
                        vh_combo += 1;
                    } else {
                        break;
                    }
                }
            }
            for (let i = 1; i < 5; i++) {
                let new_x = x - i;
                let new_y = y - i;
                if (new_x < this.chessman_count &&
                    new_y < this.chessman_count &&
                    new_x >= 0 &&
                    new_y >= 0) {
                    let info = this.chessBoardInfo[new_x][new_y];
                    if (info && info.gridType == type) {
                        vh_combo += 1;
                    } else {
                        break;
                    }
                }
            }
            let l_vh_combo = 1;
            for (let i = 1; i < 5; i++) {
                let new_x = x + i;
                let new_y = y - i;
                if (new_x < this.chessman_count &&
                    new_y < this.chessman_count &&
                    new_x >= 0 &&
                    new_y >= 0) {
                    let info = this.chessBoardInfo[new_x][new_y];
                    if (info && info.gridType == type) {
                        l_vh_combo += 1;
                    } else {
                        break;
                    }
                }
            }
            for (let i = 1; i < 5; i++) {
                let new_x = x - i;
                let new_y = y + i;
                if (new_x < this.chessman_count &&
                    new_y < this.chessman_count &&
                    new_x >= 0 &&
                    new_y >= 0) {
                    let info = this.chessBoardInfo[new_x][new_y];
                    if (info && info.gridType == type) {
                        l_vh_combo += 1;
                    } else {
                        break;
                    }
                }
            }
            let max_combo = Math.max(v_combo, h_combo, vh_combo, l_vh_combo);
            return max_combo;
        }
    }
    GoBangGameManager.rewardYuXi = 10;
