    class ScratchTicketDialogUI extends ui.ui_dialog.ScratchTicketDialogUI {
        constructor() {
            super(...arguments);
            this._rewardKey = '';
            this._rewardIndexs = [];
            this._rewardNum = 0;
            this._isOpen = false;
            this.totalColorNum = 0;
            this.curColorNum = 0;
            this.targetDis = 5000;
            this._curDis = 0;
            this._prePos = null;
            this._touchId = -1;
            this._btnLock = false;
            this._devilEvent = false;
            this._devilIndexs = [];
        }
        onEnable() {
            L3D.ondown(this.maskIcon, this, this.downTouch);
            L3D.onmove(this.maskIcon, this, this.moveTouch);
            L3D.onup(this.maskIcon, this, this.upTouch);
            L3D.onout(this.maskIcon, this, this.outTouch);
            L3D.onclick(this.openBtn, this, this.openBtnClick);
            L3D.onclick(this.backBtn, this, this.backBtnClick);
            L3D.onclick(this.bg, this, this.bgTouch);
        }
        onDisable() {
            Laya.timer.clearAll(this);
            L3D.offdown(this.maskIcon, this, this.downTouch);
            L3D.offmove(this.maskIcon, this, this.moveTouch);
            L3D.offup(this.maskIcon, this, this.upTouch);
            L3D.offout(this.maskIcon, this, this.outTouch);
            L3D.offclick(this.openBtn, this, this.openBtnClick);
            L3D.offclick(this.backBtn, this, this.backBtnClick);
            L3D.offclick(this.bg, this, this.bgTouch);
        }
        bgTouch() {
            if (this._btnLock)
                return;
            if (this._isOpen) {
                this._btnLock = true;
                this.backBtn.visible = false;
                this.closeView();
            }
        }
        downTouch(e) {
            this._touchId = e.touchId;
            let x = e.target.mouseX;
            let y = e.target.mouseY;
            let curPos = new Laya.Vector2(x, y);
            this._prePos = curPos;
        }
        moveTouch(e) {
            let x = e.target.mouseX;
            let y = e.target.mouseY;
            this.interactionArea.graphics.drawCircle(x, y, 20, "#0000ff");
            let curPos = new Laya.Vector2(x, y);
            if (this._prePos) {
                this.interactionArea.graphics.drawLine(this._prePos.x, this._prePos.y, x, y, "#0000ff", 40);
                this._curDis += Util.twoPointDistance(this._prePos.clone(), curPos);
                this._prePos = curPos;
            } else {
                this._prePos = curPos;
            }
        }
        upTouch() {
            this.caculateEnd();
        }
        outTouch() {
            this.caculateEnd();
        }
        openBtnClick() {
            if (this._btnLock)
                return;
            this._showRewardEnd();
        }
        backBtnClick() {
            if (this._btnLock)
                return;
            this._btnLock = true;
            this.backBtn.visible = false;
            this.closeView();
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.lottery);
            if (!this.interactionArea) {
                this.interactionArea = new Laya.Sprite();
                this.interactionArea.blendMode = "destination-out";
                this.interactionArea.graphics.clear();
                this.maskIcon.addChild(this.interactionArea);
            }
            this.maskIcon.cacheAs = "bitmap";
        }
        onOpened(coin) {
            this.CoinLabel.text = (coin ? coin : 0) + '';
            this._initView();
            this.ani1.play(0, false);
            StorageManager.instance.keyPointRecord.lotteryTime++;
        }
        _initView() {
            DailyTaskManager.Instance.addDailyTaskProgress(DailyTaskID.scrath, 1);
            this.openBtn.visible = false;
            this.backBtn.visible = false;
            this._btnLock = false;
            ScratchTicketManager.playTwice++;
            let bigReward = false;
            let r = Math.random() * 1;
            if (ScratchTicketManager.playTwice % ScratchTicketManager.bigReward_tiwce == 0 &&
                StorageManager.instance.scratchBigRewradTiwce < 3 &&
                StorageManager.instance.keyPointRecord.lotteryBigWinTime < 1) {
                if (r <= ScratchTicketManager.bigRewradRate) {
                    StorageManager.instance.scratchBigRewradTiwce++;
                    bigReward = true;
                } else {}
            } else {}
            if (!bigReward && ScratchTicketManager.playTwice % ScratchTicketManager.getDeivlTiwce() == 0) {
                let devil_rate = ScratchTicketManager.getDevilRate();
                if (r <= devil_rate) {
                    this._devilEvent = true;
                }
            }
            let keys = Object.keys(ScratchTicketManager.config);
            let fisrtArr = Util.chooseArrExpert(keys, ["100"]);
            this._rewardKey = ScratchTicketManager.getRandomRewardID(fisrtArr);
            let msg = ScratchTicketManager.getInfoByID(this._rewardKey);
            if (msg) {
                this.targetIcon.skin = msg.url;
            }
            var data = [];
            let exportArr = this._devilEvent ? [this._rewardKey] : [this._rewardKey, "100"];
            let newArr = Util.chooseArrExpert(keys, exportArr);
            let cell_num = 9;
            let deviel_index = -1;
            if (this._devilEvent) {
                deviel_index = Math.random() * cell_num;
                deviel_index = Math.floor(deviel_index);
            }
            let bigReward_index = -1;
            if (bigReward) {
                bigReward_index = Math.random() * cell_num;
                bigReward_index = Math.floor(bigReward_index);
            }
            if (newArr && newArr.length > 0) {
                for (let m = 0; m < cell_num; m++) {
                    let random = Math.random();
                    let rate = ScratchTicketManager.getRewardRate(bigReward);
                    let reward = 1;
                    let key = newArr[Math.floor(Math.random() * newArr.length)];
                    if (!this._devilEvent && rate >= random) {
                        reward = 2;
                        key = this._rewardKey;
                    }
                    if (bigReward) {
                        if (this._rewardKey == key || m == bigReward_index) {
                            reward = 3;
                            key = this._rewardKey;
                        }
                    }
                    let coin = ScratchTicketManager.getRewardCoin(reward);
                    if (this._devilEvent) {
                        let devil_r = ScratchTicketManager.getDevilCellRate();
                        if (devil_r >= random || m == deviel_index) {
                            reward = 1;
                            key = 100;
                            coin = 0;
                            this._devilIndexs.push(m);
                        }
                    }
                    let info = ScratchTicketManager.getInfoByID(key);
                    data.push({
                        coin: coin + "",
                        url: info && info.url
                    });
                    if (reward != 1) {
                        this._rewardIndexs.push(m);
                        this._rewardNum += coin;
                        if (coin >= 1000000) {
                            StorageManager.instance.keyPointRecord.lotteryBigWinTime++;
                        }
                        StorageManager.instance.keyPointRecord.lotteryCoin += coin;
                    }
                }
            }
            if (!this._rewardNum || this._devilEvent) {
                this._rewardNum = 0;
            }
            this.list.array = data;
            this.list.renderHandler = Laya.Handler.create(this, this._renderList, null, false);
        }
        _renderList(cell, index) {
            let icon = cell.getChildByName("icon");
            let hBox = cell.getChildByName("HBox");
            let coinLabel = hBox.getChildByName("coinLabel");
            let dataSource = cell.dataSource;
            coinLabel && (coinLabel.text = dataSource.coin + "");
            icon && (icon.skin = dataSource.url + "");
            if (dataSource.coin <= 0) {
                hBox.visible = false;
            }
        }
        _showRewardEnd() {
            if (this._isOpen)
                return;
            ModuleReportManager.inst.updateStorage(ModuleReportName.lottery, 1);
            this._isOpen = true;
            this.openBtn.visible = false;
            this.maskIcon.visible = false;
            if (this._rewardNum > 0) {
                UIMng.instance.createTips("恭喜您，中奖了");
                StorageManager.instance.keyPointRecord.lotteryWinTime++;
            } else {
                if (!this._devilEvent) {
                    UIMng.instance.createTips("很可惜，您未中奖");
                }
            }
            if (this._devilEvent) {
                Laya.timer.once(500, this, () => __awaiter(this, void 0, void 0, function* () {
                    let skeleton = yield TempletManager.instance.getSkeleton("emo");
                    if (skeleton) {
                        this.devilTip.visible = true;
                        this.ani3.play(0, false);
                        Laya.timer.once(300, this, () => {
                            this.content.addChild(skeleton);
                            TempletManager.instance.playSkeletonAni(skeleton, false, 1);
                            skeleton.pos(this.content.width / 2, this.content.height / 2);
                            skeleton.player.on(Laya.Event.STOPPED, this, () => {
                                TempletManager.instance.playSkeletonAni(skeleton, true, 0);
                                skeleton.player.offAll(Laya.Event.STOPPED);
                                Laya.timer.once(1200, this, () => {
                                    UIMng.instance.openUIScene(UIScene.DevilEventDialog, UIZorder.dig, this.closeByDevilDialog);
                                });
                            });
                        });
                    }
                }));
            } else {
                Laya.timer.once(1000, this, () => {
                    this.backBtn.visible = true;
                });
            }
            this._showRewardEffect();
        }
        _showRewardEffect() {
            for (let i = 0; i < this.list.length; i++) {
                const child = this.list.cells[i];
                if (child && this._rewardIndexs.indexOf(i) != -1) {
                    let effect = new Laya.Image();
                    effect.skin = "assets_scratchTicket/圈圈2.png";
                    effect.anchorX = 0.5;
                    effect.anchorY = 0.5;
                    effect.scaleX = 2;
                    effect.scaleY = 2;
                    let x = child.x + child.width / 2;
                    let y = child.y + child.height / 2 - 10;
                    this.rewardEffect.addChild(effect);
                    effect.pos(x, y);
                    Laya.Tween.to(effect, {
                        scaleX: 1,
                        scaleY: 1
                    }, 300);
                } else if (child && this._devilIndexs.indexOf(i) != -1) {
                    let effect = new Laya.Image();
                    effect.skin = "assets_scratchTicket/圈圈2-1.png";
                    effect.anchorX = 0.5;
                    effect.anchorY = 0.5;
                    effect.scaleX = 2;
                    effect.scaleY = 2;
                    let x = child.x + child.width / 2;
                    let y = child.y + child.height / 2 - 10;
                    this.rewardEffect.addChild(effect);
                    effect.pos(x, y);
                    Laya.Tween.to(effect, {
                        scaleX: 1,
                        scaleY: 1
                    }, 300);
                }
            }
        }
        caculateEnd(type = 2) {
            this._touchId = -1;
            this._prePos = null;
            if (type == 1) {
                this.curColorNum = this.totalColorNum - this.getProgressrByPixels();
                let rate = this.curColorNum / this.totalColorNum;
                if (this.totalColorNum && rate >= 0.9) {
                    this._showRewardEnd();
                    return true;
                }
            } else if (type == 2) {
                if (this._curDis >= 2000 && this._curDis < this.targetDis) {
                    this.openBtn.visible = true;
                }
                if (this._curDis >= this.targetDis) {
                    this._showRewardEnd();
                    return true;
                }
            }
            return false;
        }
        getProgressrByPixels() {
            let gl = Laya["LayaGL"].instance;
            let pixels = new Uint8Array(gl.drawingBufferWidth * gl.drawingBufferHeight * 4);
            let real_h = (gl.drawingBufferHeight - 1334) + (1334 - 367 - 600);
            gl.readPixels(165, real_h, 540, 600, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
            let count = 0;
            for (let i = 0; i < pixels.length; i += 4) {
                let r = pixels[i];
                let g = pixels[i + 1];
                let b = pixels[i + 2];
                let a = pixels[i + 3];
                if (r == 255 && g == 255 && b == 255) {
                    count++;
                } else if (r == 255 && g == 0 && b == 0) {} else {}
            }
            return count;
        }
        closeByDevilDialog() {
            GameEvent.ev(GameEV.scratchTicketFinish, this._rewardNum);
            UIMng.instance.closeUIScene(UIScene.ScratchTicketDialog);
        }
        closeView() {
            this.ani2.play(0, false);
            Laya.timer.once(700, this, () => {
                GameEvent.ev(GameEV.scratchTicketFinish, this._rewardNum);
                UIMng.instance.closeUIScene(UIScene.ScratchTicketDialog);
            });
        }
    }

