    class GameSheepTalkDialogUI extends ui.ui_dialog.SheepGameTalkDialogUI {
        constructor() {
            super(...arguments);
            this._isBtnLock = false;
            this._talkType = -1;
            this._talkInfos = [];
            this._talkIndex = 0;
        }
        onAwake() {}
        onEnable() {
            L3D.onclick(this.btnNext, this, this._next);
            L3D.onclick(this.gpSelect, this, this._nothing);
            L3D.onclick(this.select1, this, this._selectBtnClick, [1]);
            L3D.onclick(this.select2, this, this._selectBtnClick, [2]);
        }
        onDisable() {
            L3D.offclick(this.btnNext, this, this._next);
            L3D.offclick(this.gpSelect, this, this._nothing);
            L3D.offclick(this.select1, this, this._selectBtnClick);
            L3D.offclick(this.select2, this, this._selectBtnClick);
        }
        onOpened(info) {
            this._talkType = info.type;
            this._talkInfos = info.talks;
            this.gpDialog.visible = false;
            this.gpSelect.visible = false;
            this._updateTalk(this._talkIndex);
            this.coinLabel.text = "+" + GameSheepManager.rewardCoin;
            this.statuLabel.text = "+" + GameSheepManager.rewardStatu;
            this.yuxiLabel.text = "+" + GameSheepManager.rewardYuXi;
        }
        _nothing() {}
        _next() {
            if (this._isBtnLock)
                return;
            let index = ++this._talkIndex;
            let talkInfo = this._talkInfos[index];
            if (!talkInfo && this._talkType == 2) {
                GameEvent.ev(GameEV.sheepGameGetReward);
                this.closeView();
            }
            this._updateTalk(index);
        }
        _selectBtnClick(isChallange) {
            if (StorageManager.instance.Level < 7 &&
                isChallange == 2) {
                isChallange = 3;
            }
            GameEvent.ev(GameEV.sheepGameChallange, isChallange);
            this.closeView();
        }
        _updateTalk(index) {
            let talkInfo = this._talkInfos[index];
            if (talkInfo) {
                if (talkInfo.guideType == 1) {
                    this.gpDialog.visible = true;
                    this.gpSelect.visible = false;
                    this.textDialog.text = talkInfo.desc;
                } else {
                    this.gpDialog.visible = false;
                    this.gpSelect.visible = true;
                }
            } else {}
        }
        closeView() {
            UIMng.instance.closeUIScene(UIScene.GameSheepTalkDialog);
        }
    }

    class specialEventDialogUI extends ui.ui_dialog.SpecialEventDialogUI {
        constructor() {
            super(...arguments);
            this._index = 0;
            this._isend = false;
            this._rewardCoin = 0;
            this._rewardStatu = 0;
            this._pop = false;
            this._iscorrect = false;
            this._isvideo = false;
        }
        onAwake() {
            this.gpSelect.visible = this.gpDialog.visible = this.gpMask.visible = false;
            this.textList.array = [];
            this.textList.renderHandler = Laya.Handler.create(this, this._renderText, null, false);
            this.selectList.array = [];
            this.selectList.renderHandler = Laya.Handler.create(this, this._renderSelect, null, false);
        }
        onOpened(param) {
            return __awaiter(this, void 0, void 0, function* () {
                this._type = param.type;
                this._config = yield SpecialEventManager.instance.getConfig(param.type);
                switch (this._type) {
                    case specialEventType.goldShit:
                        ModuleReportManager.inst.reportModuleEnter(ModuleReportName.shit);
                        this._refreshInfo(2200);
                        break;
                    case specialEventType.oldman:
                        ModuleReportManager.inst.reportModuleEnter(ModuleReportName.oldman);
                        if (param.para_a) {
                            this._index = 3;
                            this._iscorrect = true;
                        }
                        this._refreshInfo();
                        break;
                    default:
                        break;
                }
            });
        }
        onEnable() {
            L3D.onclick(this.btnNext, this, this._next);
            L3D.onclick(this.gpSelect, this, this._nothing);
            GameEvent.on(GameEV.specialEventRefresh, this, this._selected);
        }
        onDisable() {
            L3D.offclick(this.btnNext, this, this._next);
            L3D.offclick(this.gpSelect, this, this._nothing);
            GameEvent.off(GameEV.specialEventRefresh, this, this._selected);
        }
        _next() {
            if (this._pop) {
                UIMng.instance.openUIScene(UIScene.specialAnswerDialog, UIZorder.dig, {
                    type: this._type,
                    iscorrect: this._iscorrect
                });
            }
            if (this._isend) {
                this._close();
                return;
            }
            if (this._pop)
                return;
            this._index++;
            this._refreshInfo();
        }
        _nothing() {}
        _renderText(cell, index) {
            let data = cell.dataSource;
            let lb = cell.getChildAt(0);
            if (data.indexOf("X") !== -1) {
                let reward = SpecialEventManager.instance.getReward(this._type);
                let temp = data.replace("X", reward + "");
                lb.text = temp;
            } else if (data.indexOf("Y") !== -1) {
                let punish = GameMgr.sceneTag == SceneTag.mainGame ? specailFail : specailFail_2;
                let temp = data.replace("Y", punish + "");
                lb.text = temp;
            } else {
                lb.text = data;
            }
        }
        _renderSelect(cell, index) {
            let data = cell.dataSource;
            let lb = cell.getChildByName("textSelect");
            lb.text = data;
            cell.on(Laya.Event.CLICK, this, this._selectChoose, [index]);
        }
        _refreshInfo(delay = 0) {
            return __awaiter(this, void 0, void 0, function* () {
                let config = this._config[this._index];
                if (!config) {
                    this._close();
                    return;
                }
                this.gpSelect.visible = this.gpDialog.visible = this.gpMask.visible = false;
                if (config.isEnd) {
                    this._isend = true;
                }
                if (config.pop) {
                    this._pop = true;
                } else {
                    this._pop = false;
                }
                let cb = () => {
                    switch (config.type) {
                        case guideType.aside:
                            this.textTitle.text = "旁白";
                            this.imgCharacter.visible = false;
                            this.imgTitle.x = -15;
                            this.gpDialog.visible = true;
                            this.textList.array = config.desc;
                            this.textList.refresh();
                            break;
                        case guideType.playerDialog:
                            this.textTitle.text = "小女子";
                            this.imgCharacter.skin = "assets_common/character/queen_1.png";
                            this.imgCharacter.scaleX = -1.5;
                            this.imgCharacter.x = 618;
                            this.imgTitle.x = 457;
                            this.imgCharacter.visible = true;
                            this.gpDialog.visible = true;
                            this.textList.array = config.desc;
                            this.textList.refresh();
                            break;
                        case guideType.npcDialog:
                            this.textTitle.text = config.roleName;
                            this.imgCharacter.skin = "assets_common/character/" + config.role + ".png";
                            this.imgCharacter.scaleX = 1.5;
                            this.imgCharacter.x = 132;
                            this.imgTitle.x = -15;
                            this.imgCharacter.visible = true;
                            this.gpDialog.visible = true;
                            this.textList.array = config.desc;
                            this.textList.refresh();
                            break;
                        case guideType.select:
                            this.selectList.array = config.desc;
                            this.selectList.refresh();
                            this.gpSelect.visible = true;
                            break;
                    }
                    this.gpMask.visible = config.ismask;
                };
                if (delay) {
                    Laya.timer.once(delay, this, () => {
                        cb();
                    });
                } else {
                    cb();
                }
            });
        }
        _close() {
            if (this._isvideo) {
                SpecialEventManager.instance.updateTime(this._type);
            }
            switch (this._type) {
                case specialEventType.goldShit:
                    GameMgr.currentSceneCtrl.shitholeCtrl.hideNpc(this._rewardCoin);
                    SpecialEventManager.instance.unlockGoldEvent();
                    break;
                case specialEventType.oldman:
                    GameEvent.ev(GameEV.removeNpc, specialEventType.oldman);
                    SpecialEventManager.instance.unlockOldmanEvent();
                    let pos = GameMgr.sceneTag == SceneTag.mainGame ? oldmanEndPos[0] : oldmanEndPos[1];
                    let vec3 = new Laya.Vector3(pos.x, pos.y, pos.z);
                    GameMgr.currentSceneCtrl.createCoins(this._rewardCoin, vec3);
                    GameMgr.currentSceneCtrl.createStatus(this._rewardStatu, vec3);
                    break;
                default:
                    break;
            }
            UIMng.instance.closeUIScene(UIScene.specialEventDialog);
        }
        _justClose() {
            UIMng.instance.closeUIScene(UIScene.specialEventDialog);
        }
        _selectChoose(index) {
            let answer;
            switch (this._type) {
                case specialEventType.goldShit:
                    answer = SpecialEventManager.instance.shit_correct_index;
                    if (index == answer) {
                        this._iscorrect = true;
                        this._index++;
                    } else {
                        if (index == 2) {
                            UIMng.instance.createTips("做人要诚实");
                        } else {
                            UIMng.instance.createTips("你肯定是看错了");
                        }
                        this._iscorrect = false;
                        this._index += 2;
                    }
                    this._refreshInfo();
                    break;
                case specialEventType.oldman:
                    if (index == 0) {
                        this._justClose();
                        GameEvent.ev(GameEV.operateNpc, specialEventType.oldman);
                    } else {
                        this._iscorrect = false;
                        this._index++;
                        this._refreshInfo();
                    }
                    break;
                default:
                    break;
            }
        }
        _selected(data) {
            this._isvideo = data.isvideo;
            this._rewardCoin = data.reward;
            this._rewardStatu = data.rewardStatu ? data.rewardStatu : 0;
            if (data.reward < 0) {
                this._index += 1;
                this._refreshInfo();
            } else {
                if (data.isvideo) {
                    this._index += 2;
                    this._refreshInfo();
                } else {
                    this._index += 3;
                    this._refreshInfo();
                }
            }
        }
    }

