    class guideDialogUI extends ui.ui_dialog.guideDialogUI {
        onAwake() {
            this._refreshInfo();
            this.JoyPanel.x = Laya.stage.width / 2;
            this.JoyPanel.y = Laya.stage.height * 0.8;
            if (GameMgr.sceneTag !== SceneTag.shitGame) {
                GameMgr.currentSceneCtrl.CameraCtrl.closeUp();
            } else {
                this.select1.getChildAt(0).text = "想";
                this.select2.getChildAt(0).text = "十分想";
                this.select3.getChildAt(0).text = "超级无敌想";
            }
        }
        onEnable() {
            L3D.onclick(this.btnNext, this, this._next);
            L3D.onclick(this.gpSelect, this, this._nothing);
            L3D.onclick(this.select1, this, this._selectShit, [0]);
            L3D.onclick(this.select2, this, this._selectShit, [1]);
            L3D.onclick(this.select3, this, this._selectShit, [2]);
            GameEvent.on(GameEV.refreshGuide, this, this._refreshInfo);
            GameEvent.on(GameEV.Joy_Move, this, this._hideMask);
            GameEvent.on(GameEV.isPlayerFull, this, this._stepCheck);
        }
        onDisable() {
            L3D.offclick(this.btnNext, this, this._next);
            L3D.offclick(this.gpSelect, this, this._nothing);
            L3D.offclick(this.select1, this, this._selectShit);
            L3D.offclick(this.select2, this, this._selectShit);
            L3D.offclick(this.select3, this, this._selectShit);
            GameEvent.off(GameEV.refreshGuide, this, this._refreshInfo);
            GameEvent.off(GameEV.Joy_Move, this, this._hideMask);
            GameEvent.off(GameEV.isPlayerFull, this, this._stepCheck);
        }
        _next() {
            this._clickGuidePoint();
            GuideManager.instance.GuideIndex++;
            this._stepCheck();
        }
        _refreshInfo(delay = 0) {
            this.gpSelect.visible = this.gpTips.visible = this.gpDialog.visible = this.gpMask.visible = false;
            let config = GuideManager.instance.getCurrentConfig();
            if (!config) {
                this._close();
                return;
            }
            let cb = () => {
                switch (config.type) {
                    case guideType.aside:
                        this.textTitle.text = "旁白";
                        this.textDialog.text = config.desc;
                        this.imgCharacter.visible = false;
                        this.imgTitle.x = -15;
                        this.gpDialog.visible = true;
                        break;
                    case guideType.playerDialog:
                        this.textTitle.text = "小女子";
                        this.textDialog.text = config.desc;
                        this.imgCharacter.skin = "assets_common/character/queen_1.png";
                        this.imgCharacter.scaleX = -1.5;
                        this.imgCharacter.x = 618;
                        this.imgTitle.x = 457;
                        this.imgCharacter.visible = true;
                        this.gpDialog.visible = true;
                        GameEvent.ev(GameEV.Joy_End);
                        break;
                    case guideType.npcDialog:
                        this.textTitle.text = "神秘老人";
                        this.textDialog.text = config.desc;
                        this.imgCharacter.skin = "assets_common/character/oldman.png";
                        this.imgCharacter.scaleX = 1.5;
                        this.imgCharacter.x = 132;
                        this.imgTitle.x = -15;
                        this.imgCharacter.visible = true;
                        this.gpDialog.visible = true;
                        GameEvent.ev(GameEV.Joy_End);
                        break;
                    case guideType.tips:
                        this.gpTips.width = 40 * config.desc.length;
                        if (this.gpTips.width > 750)
                            this.gpTips.width = 750;
                        this.textTips.text = config.desc;
                        this.gpTips.visible = true;
                        break;
                    case guideType.select:
                        this.gpSelect.visible = true;
                        break;
                }
                this.gpMask.visible = config.ismask;
                if (config.isEnd) {
                    Laya.timer.once(2000, this, () => {
                        Laya.Tween.to(this, {
                            aplha: 0
                        }, 500, null, Laya.Handler.create(this, () => {
                            GuideManager.instance.GuideOver();
                            this._close();
                        }));
                    });
                }
                this._addLineCheck();
            };
            if (delay) {
                Laya.timer.once(delay, this, () => {
                    cb();
                });
            } else {
                cb();
            }
            this._renderGuidePoint();
        }
        _renderGuidePoint() {
            switch (GuideManager.instance.GuideIndex) {
                case 0:
                    SDKManager.instance.reportUserGuide(2);
                    break;
                case 1:
                    SDKManager.instance.reportUserGuide(4);
                    break;
                case 2:
                    SDKManager.instance.reportUserGuide(6);
                    break;
                case 5:
                    SDKManager.instance.reportUserGuide(12);
                    break;
                case 8:
                    SDKManager.instance.reportUserGuide(17);
                    break;
                case 9:
                    SDKManager.instance.reportUserGuide(19);
                    break;
                case 10:
                    SDKManager.instance.reportUserGuide(21);
                    break;
                case 12:
                    SDKManager.instance.reportUserGuide(23);
                    break;
                case 13:
                    SDKManager.instance.reportUserGuide(24);
                    break;
                case 14:
                    SDKManager.instance.reportUserGuide(25);
                    break;
                case 15:
                    SDKManager.instance.reportUserGuide(29);
                    break;
                case 16:
                    SDKManager.instance.reportUserGuide(30);
                    SDKManager.instance.reportUserAction(5);
                    break;
            }
        }
        _clickGuidePoint() {
            switch (GuideManager.instance.GuideIndex) {
                case 0:
                    SDKManager.instance.reportUserGuide(3);
                    SDKManager.instance.reportUserAction(2);
                    break;
                case 1:
                    SDKManager.instance.reportUserGuide(5);
                    break;
                case 5:
                    SDKManager.instance.reportUserGuide(13);
                    break;
                case 7:
                    SDKManager.instance.reportUserGuide(16);
                    break;
                case 8:
                    SDKManager.instance.reportUserGuide(18);
                    break;
                case 9:
                    SDKManager.instance.reportUserGuide(20);
                    break;
                case 10:
                    SDKManager.instance.reportUserGuide(22);
                    SDKManager.instance.reportUserAction(4);
                    break;
            }
        }
        _close() {
            UIMng.instance.closeUIScene(UIScene.guideDialog);
        }
        _hideMask() {
            if (GameMgr.sceneTag !== SceneTag.mainGame)
                return;
            GameEvent.off(GameEV.Joy_Move, this, this._hideMask);
            this.gpMask.visible = false;
            GuideManager.instance.GuideIndex = 3;
            this._refreshInfo();
            SDKManager.instance.reportUserGuide(7);
            SDKManager.instance.reportUserAction(3);
        }
        _stepCheck(data) {
            if (GameMgr.sceneTag == SceneTag.mainGame) {
                switch (GuideManager.instance.GuideIndex) {
                    case 2:
                        GameMgr.currentSceneCtrl.CameraCtrl.recoverCloseup();
                        GameMgr.currentSceneCtrl.propProductions[productType.shit][0].createGuideShit();
                        break;
                    case 3:
                        if (data) {
                            GuideManager.instance.GuideIndex++;
                            GC.gm.currentSceneCtrl.shitholeCtrl.addArrow();
                            this._refreshInfo();
                        }
                        break;
                    case 11:
                        GC.gm.currentSceneCtrl.shitholeCtrl.hideNpc();
                        break;
                    default:
                        break;
                }
            } else {
                switch (GuideManager.instance.GuideIndex) {
                    case 0:
                        if (data) {
                            GuideManager.instance.GuideIndex++;
                            GC.gm.currentSceneCtrl.shitholeCtrl.addArrow();
                            this._refreshInfo();
                        }
                        break;
                    case 5:
                        GC.gm.currentSceneCtrl.shitholeCtrl.hideNpc();
                        break;
                    default:
                        break;
                }
            }
        }
        _addLineCheck() {
            let ctrl = GameMgr.currentSceneCtrl;
            switch (GuideManager.instance.GuideIndex) {
                case 12:
                    let target = ctrl.saleAreaRoot.getChildByName("leek_1").getChildByName("buildPos");
                    ctrl.createGuideLine(target.transform.position);
                    break;
                case 13:
                    let target2 = ctrl.productAreaRoot.getChildByName("leek_1").getChildByName("buildPos");
                    ctrl.createGuideLine(target2.transform.position);
                    break;
                default:
                    break;
            }
        }
        _nothing() {}
        _selectShit(index) {
            if (GameMgr.sceneTag == SceneTag.shitGame) {
                GuideManager.instance.GuideIndex++;
                this._refreshInfo();
                return;
            }
            switch (index) {
                case 0:
                    UIMng.instance.createTips("做人要诚实");
                    this.select1.visible = false;
                    break;
                case 1:
                    UIMng.instance.createTips("做人要诚实");
                    this.select2.visible = false;
                    break;
                case 2:
                    GuideManager.instance.GuideIndex++;
                    this._refreshInfo();
                    SDKManager.instance.reportUserGuide(14);
                    SDKManager.instance.reportUserGuide(15);
                    break;
            }
        }
    }

    class guideDialogGuardUI extends ui.ui_dialog.guideDialogGuardUI {
        constructor() {
            super(...arguments);
            this._cur_guide_index = 0;
            this.guide_config = [{
                    "name": "兢兢业业的警卫",
                    "ismask": false,
                    "type": 2,
                    "desc": "大人，最近宫内事务有慵懒之风~ \n 需要雇佣我整顿风气么？",
                },
                {
                    "name": "兢兢业业的警卫",
                    "ismask": false,
                    "type": 4,
                    "desc": ""
                },
                {
                    "name": "兢兢业业的警卫",
                    "ismask": false,
                    "type": 2,
                    "desc": "我在任的期间一定会好好帮你整顿风气的~",
                    "isEnd": true
                },
                {
                    "name": "兢兢业业的警卫",
                    "ismask": false,
                    "type": 2,
                    "desc": "TvT，下次记得来找我哦",
                    "isEnd": true
                }
            ];
            this._lock = false;
            this._videosuccess = false;
        }
        onAwake() {
            this._cur_guide_index = 0;
            let config = this.guide_config[this._cur_guide_index];
            this._refreshInfo(config);
            this.JoyPanel.x = Laya.stage.width / 2;
            this.JoyPanel.y = Laya.stage.height * 0.8;
            GameMgr.currentSceneCtrl.CameraCtrl.closeUp();
        }
        onEnable() {
            L3D.onclick(this.btnNext, this, this._next);
            L3D.onclick(this.gpSelect, this, this._nothing);
            L3D.onclick(this.select1, this, this._selectShit, [0]);
            L3D.onclick(this.select2, this, this._selectShit, [1]);
        }
        onDisable() {
            L3D.offclick(this.btnNext, this, this._next);
            L3D.offclick(this.gpSelect, this, this._nothing);
            L3D.offclick(this.select1, this, this._selectShit);
            L3D.offclick(this.select2, this, this._selectShit);
        }
        _next() {
            this._stepCheck();
        }
        _refreshInfo(config, delay = 0) {
            this.gpSelect.visible = this.gpDialog.visible = this.gpMask.visible = false;
            if (!config) {
                this._close();
                return;
            }
            let cb = () => {
                switch (config.type) {
                    case guideType.npcDialog:
                        this.textDialog.text = config.desc;
                        this.imgCharacter.visible = true;
                        this.gpDialog.visible = true;
                        break;
                    case guideType.select:
                        this.gpSelect.visible = true;
                        break;
                }
                this.gpMask.visible = config.ismask;
                if (config.isEnd) {
                    Laya.timer.once(2000, this, () => {
                        Laya.Tween.to(this, {
                            aplha: 0
                        }, 500, null, Laya.Handler.create(this, () => {
                            this._close();
                        }));
                    });
                }
                this._addLineCheck();
            };
            if (delay) {
                Laya.timer.once(delay, this, () => {
                    cb();
                });
            } else {
                cb();
            }
            this._renderGuidePoint();
        }
        _renderGuidePoint() {}
        _clickGuidePoint() {}
        _close() {
            GameEvent.ev(GameEV.off_npc_talk_end);
            GameMgr.currentSceneCtrl.CameraCtrl.recoverCloseup();
            UIMng.instance.closeUIScene(UIScene.guideDialogGuard);
            if (this._videosuccess) {
                GameEvent.ev(GameEV.guardTalkEnd, true);
            } else {
                GameEvent.ev(GameEV.guardTalkEnd, false);
            }
        }
        _stepCheck() {
            let cur_guide = this.guide_config[this._cur_guide_index];
            if (!cur_guide.isEnd) {
                this._cur_guide_index += 1;
                let next_config = this.guide_config[this._cur_guide_index];
                this._refreshInfo(next_config, 100);
            } else {
                this._close();
            }
        }
        _addLineCheck() {}
        _nothing() {}
        _selectShit(index) {
            if (this._lock)
                return;
            this._lock = true;
            let config;
            switch (index) {
                case 0:
                    let cb = () => {
                        this._cur_guide_index = 2;
                        config = this.guide_config[this._cur_guide_index];
                        this._refreshInfo(config);
                        this._lock = false;
                        this._videosuccess = true;
                    };
                    let failcb = () => {
                        this._lock = false;
                    };
                    SDKManager.instance.ShareOrVideo(ShareLoc.callGuard, cb, failcb);
                    break;
                case 1:
                    this._cur_guide_index = 3;
                    config = this.guide_config[this._cur_guide_index];
                    this._refreshInfo(config);
                    break;
            }
        }
    }

