    class levelUpDialogUI extends ui.ui_dialog.levelUpDialogUI {
        constructor() {
            super(...arguments);
            this._costCoin = 0;
            this._statusAdd = 0;
            this._limit = 0;
        }
        onOpened(showFinger) {
            if (showFinger)
                this.gpFinger.visible = true;
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.rolelevel);
            let current_config = RoleLevelManager.instance.getConfigByLevel(StorageManager.instance.Level);
            this.c1.skin = `assets_common/character/queen_${current_config.modelid}.png`;
            this.c1Name.text = current_config.name;
            this.c1Speed.text = Math.floor(current_config.speed * 100) + "";
            this.c1Bearload.text = current_config.power + "";
            let next_config = RoleLevelManager.instance.getConfigByLevel(StorageManager.instance.Level + 1);
            this.c2.skin = `assets_common/character/queen_${next_config.modelid}.png`;
            this.c2Name.text = next_config.name;
            this.c2Speed.text = Math.floor(next_config.speed * 100) + "";
            this.c2Bearload.text = next_config.power + "";
            let currentStatus = RoleLevelManager.instance.getCurrentStatus(StorageManager.instance.Level);
            this.c1Status.text = "" + currentStatus;
            this.c2Status.text = "" + (currentStatus + next_config.statusadd);
            this._costCoin = next_config.cost;
            this.txtCost.text = next_config.cost + "";
            this._statusAdd = next_config.statusadd;
            this._limit = next_config.statuslimit;
            this.currentStatus.text = StorageManager.instance.SocialStatus + "";
            this.limitStatus.text = " / " + next_config.statuslimit;
            this.limitStatus.x = 17 * this.currentStatus.text.length;
            let length = this.currentStatus.text.length + this.limitStatus.text.length;
            this.limitGp.centerX = -100 - length;
            if (this._limit > StorageManager.instance.SocialStatus) {
                this.currentStatus.color = "#ED4E4E";
            } else {
                this.currentStatus.color = "#FFFFFF";
            }
        }
        onEnable() {
            L3D.onclick(this.bg, this, this._close);
            L3D.onclick(this.btnLevelup, this, this._levelup);
            L3D.onclick(this.QAStatus, this, this._QAStatusClick);
            L3D.onclick(this.QAStatus2, this, this._QAStatusClick);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this._close);
            L3D.offclick(this.btnLevelup, this, this._levelup);
            L3D.offclick(this.QAStatus, this, this._QAStatusClick);
            L3D.offclick(this.QAStatus2, this, this._QAStatusClick);
        }
        _close() {
            UIMng.instance.closeUIScene(UIScene.levelUpDialog);
        }
        _levelup() {
            this.gpFinger.visible = false;
            if (StorageManager.instance.Coin < this._costCoin) {
                UIMng.instance.createCoinTips();
                return;
            }
            if (this._limit > StorageManager.instance.SocialStatus) {
                UIMng.instance.createSocialTips();
                return;
            }
            StorageManager.instance.Coin -= this._costCoin;
            StorageManager.instance.SocialStatus += this._statusAdd;
            this._close();
            StorageManager.instance.Level++;
            StorageManager.instance.syncData();
            UIMng.instance.createTips("身份提升成功，离女皇又进一步了");
            ModuleReportManager.inst.updateStorage(ModuleReportName.rolelevel, StorageManager.instance.Level);
        }
        _QAStatusClick() {
            UIMng.instance.openUIScene(UIScene.gameTipDialog, UIZorder.dig, GameTip.statuRule);
        }
    }

    class missionDetailDialogUI extends ui.ui_dialog.missionDetailDialogUI {
        constructor() {
            super(...arguments);
            this._config = null;
            this._btnLock = false;
            this._close_later_time = 0;
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.task);
            let config = MissionManager.instance.getCurrentMission();
            this._config = config;
            let progress = MissionManager.instance.progress;
            let condition = config.condition;
            let rate = progress / condition;
            this.txtProgress.text = `${progress}/${condition}`;
            this.barMissionProgress.width = 214 * rate;
            this.txtDesc.text = config.decs;
            this.txtReward.text = "+" + config.reward;
            this.btnGetReward.visible = MissionManager.instance.isfinish;
            this.videoGetBtn.visible = MissionManager.instance.isfinish;
            this.btnGo.visible = !MissionManager.instance.isfinish;
            this.gpFinger.visible = !MissionManager.instance.hideFinger;
            this.complete_tip.visible = MissionManager.instance.isfinish;
            this._init_gpFinger(rate, config);
            this._setVideoRateIcon(config.rewardbase);
            if (ConfigManager.instance.reportErr) {
                this.videoGetBtn.visible = false;
                this.btnGetReward.centerX = 0;
            }
            SDKManager.instance.noVideoTimes++;
        }
        _setVideoRateIcon(rate) {
            let url = '';
            switch (rate) {
                case 2:
                    url = "assets_dialog/双倍领取.png";
                    break;
                case 3:
                    url = "assets_dialog/三倍领取.png";
                    break;
                case 5:
                    url = "assets_dialog/五倍领取.png";
                    break;
                case 10:
                    url = "assets_dialog/十倍领取.png";
                    break;
                default:
                    break;
            }
            this.videoGetIcon.skin = url;
        }
        _init_gpFinger(rate, config) {
            if (rate == 1 && config.task <= 3) {
                this.gpFinger.visible = true;
                this._close_later_time = Date.now();
            } else {
                this.gpFinger.visible = false;
            }
        }
        onEnable() {
            L3D.onclick(this.btnGetReward, this, this._getReward);
            L3D.onclick(this.videoGetBtn, this, this._videoGetBtnClick);
            L3D.onclick(this.bg, this, this._on_bg);
            L3D.onclick(this.btnClose, this, this._btnCloseClick);
            L3D.onclick(this.btnGo, this, this._goingToTarget);
        }
        onDisable() {
            L3D.offclick(this.btnGetReward, this, this._getReward);
            L3D.offclick(this.videoGetBtn, this, this._videoGetBtnClick);
            L3D.offclick(this.bg, this, this._on_bg);
            L3D.offclick(this.btnClose, this, this._btnCloseClick);
            L3D.offclick(this.btnGo, this, this._goingToTarget);
        }
        _getReward() {
            if (this._btnLock)
                return;
            if (!MissionManager.instance.isfinish) {
                UIMng.instance.createTips("尚未完成任务");
                return;
            }
            SDKManager.instance.noVideoShowAd();
            MissionManager.instance.getReward();
            this._close();
            let canshare = MissionManager.instance.checkShare();
            if (canshare) {
                GameMgr.closeEnd();
            }
            GameEvent.ev(GameEV.missionAni);
        }
        _videoGetBtnClick() {
            if (!MissionManager.instance.isfinish) {
                UIMng.instance.createTips("尚未完成任务");
                return;
            }
            this._btnLock = true;
            SDKManager.instance.ShareOrVideo(ShareLoc.multiple, () => {
                let rate = 1;
                if (this._config && this._config.rewardbase) {
                    rate = this._config.rewardbase;
                };
                MissionManager.instance.getReward(rate);
                GameEvent.ev(GameEV.missionAni);
                this._btnLock = false;
                this._close();
            }, () => {
                this._btnLock = false;
            });
        }
        _on_bg() {
            if (this._btnLock)
                return;
            if ((Date.now() - this._close_later_time) < 2000)
                return;
            this._close();
        }
        _btnCloseClick() {
            if (this._btnLock)
                return;
            if (MissionManager.instance.isfinish) {
                this._close();
            } else {
                this._goingToTarget();
            }
        }
        _goingToTarget() {
            if (this._btnLock)
                return;
            MissionManager.instance.hideFinger = true;
            GameEvent.ev(GameEV.refreshMission);
            let target = MissionManager.instance.getMissionTarget();
            if (target)
                GameMgr.currentSceneCtrl.createGuideLine(target.transform.position);
            this._close();
        }
        _close() {
            if (!MissionManager.instance.isfinish) {
                let target = MissionManager.instance.getMissionTarget();
                if (target)
                    GameMgr.currentSceneCtrl.createGuideLine(target.transform.position);
            }
            UIMng.instance.closeUIScene(UIScene.missionDetailDialog);
        }
    }

    class tabCom extends Laya.Script {
        constructor() {
            super(...arguments);
            this._root = null;
            this._btns_root = null;
            this._click_cb = null;
            this._tab_index = 0;
            this.spaceX = 0;
            this._btns = [];
            this._tab_panels = [];
        }
        init(panels) {
            this._tab_panels = panels;
        }
        onAwake() {
            this._root = this.owner;
            this._btns_root = this._root.getChildByName(`btns_root`);
            this.resFile = "";
            Laya.timer.callLater(this, () => {
                for (let i = 0; i < this._btns_root.numChildren; i++) {
                    let btn = this._btns_root.getChildAt(i);
                    this._btns.push(btn);
                    btn.x = i * btn.width + this.spaceX * i;
                    btn.on(Laya.Event.MOUSE_DOWN, this, this._on_btn_click, [i]);
                    if (i == 0) {
                        btn.skin = `${this.resFile}${this.tab_on_imgs[0]}`;
                    } else {
                        btn.skin = `${this.resFile}${this.tab_off_imgs[i]}`;
                    }
                }
            });
        }
        _on_btn_click(index) {
            if (this._click_cb) {
                this._click_cb(index);
            }
            this._btns[this._tab_index].skin = `${this.resFile}${this.tab_off_imgs[this._tab_index]}`;
            this._tab_panels[this._tab_index].visible = false;
            this._btns[index].skin = `${this.resFile}${this.tab_on_imgs[index]}`;
            this._tab_panels[index].visible = true;
            this._tab_index = index;
        }
    }

    class offLineDialogUI extends ui.ui_dialog.offLineDialogUI {
        constructor() {
            super(...arguments);
            this._scene_min_coin = 0;
            this._off_line_reward = 0;
            this._tab_panels = [];
            this._scene_tag = 0;
            this.btnlock = false;
        }
        onOpened(data) {
            this._off_line_reward = data[0];
            this._scene_tag = GC.gm.sceneTag;
        }
        onAwake() {
            ModuleReportManager.inst.reportModuleEnter(ModuleReportName.offline);
            this._tab = this.tab.getComponent(tabCom);
            this._tab_panels.push(this.tab_panel_0);
            this._tab_panels.push(this.tab_panel_1);
            this._tab.init(this._tab_panels);
            Laya.timer.callLater(this, this._init_ui);
        }
        onEnable() {
            L3D.onclick(this.bg, this, this._close);
            L3D.onclick(this.btn_coin_up, this, this._level_up_coin);
            L3D.onclick(this.btn_video_up, this, this._level_up_video);
            L3D.onclick(this.btn_once_get, this, this._get_reward);
            L3D.onclick(this.btn_double_get, this, this._get_double_reward);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this._close);
            L3D.offclick(this.btn_coin_up, this, this._level_up_coin);
            L3D.offclick(this.btn_video_up, this, this._level_up_video);
            L3D.offclick(this.btn_once_get, this, this._get_reward);
            L3D.offclick(this.btn_double_get, this, this._get_double_reward);
        }
        _init_ui() {
            this._get_scene_min();
            this.lab_scene_min.text = `+${this._scene_min_coin}/分钟`;
            this.lab_off_reward.text = `${this._off_line_reward}`;
            this.img_npc.skin = OffLineManager.npc_img[this._scene_tag];
            this._refresh();
        }
        _refresh() {
            this._get_scene_min();
            let up_coin = OffLineManager.instance.get_up_level_data(this._scene_tag);
            if (up_coin == 0) {
                this.btn_coin_up.visible = false;
                this.btn_video_up.visible = true;
            } else {
                this.lab_up_level_need.text = `${up_coin}`;
                this.btn_coin_up.visible = true;
                this.btn_video_up.visible = false;
            }
            let cur_level = OffLineManager.instance.getOffLv(this._scene_tag);
            let cur_max = OffLineManager.instance.getOffMax(this._scene_tag, cur_level);
            let next_max = OffLineManager.instance.getOffMax(this._scene_tag, cur_level + 1);
            this.lab_cur_max.text = `${cur_max}`;
            this.lab_next_max.text = `${next_max}`;
            if (cur_level >= OffLineManager.instance.up_level_config[this._scene_tag].length) {
                this.btn_video_up.gray = true;
                this.btn_coin_up.gray = true;
            }
            if (this._off_line_reward <= 0) {
                this.btn_double_get.visible = false;
                this.btn_once_get.visible = false;
            } else {
                this.btn_double_get.visible = true;
                this.btn_once_get.visible = true;
            }
            if (this.btn_video_up.gray) {
                this.redTip.visible = false;
            } else {
                this.redTip.visible = true;
                this.redTipAnim.play(0, true);
            }
        }
        _get_scene_min() {
            let cur_max = OffLineManager.instance.getOffMax(this._scene_tag);
            this.lab_max_tip.visible = false;
            if (this._off_line_reward >= cur_max) {
                this.lab_max_tip.visible = true;
                this.pro_yellow.width = 140;
            } else {
                this.pro_yellow.width = 140 * this._off_line_reward / cur_max;
            }
            let min_get = 0;
            min_get = OffLineManager.instance.get_off_line_coin_minute(GC.gm.sceneTag);
            this._scene_min_coin = min_get;
        }
        _get_reward() {
            if (this.btnlock)
                return;
            ModuleReportManager.inst.updateStorage(ModuleReportName.offline, 1);
            this.btnlock = true;
            OffLineManager.instance.resetOffTime(this._scene_tag);
            OffLineManager.instance.resetSceneOffLineGetCoin(this._scene_tag);
            GameEvent.ev(GameEV.off_npc_ui_get_reward, this._off_line_reward);
            this._close();
            StorageManager.instance.keyPointRecord.offlineCoin += this._off_line_reward;
            StorageManager.instance.keyPointRecord.offlinetime++;
        }
        _get_double_reward() {
            if (this.btnlock)
                return;
            this.btnlock = true;
            let success = () => {
                ModuleReportManager.inst.updateStorage(ModuleReportName.offline, 1);
                OffLineManager.instance.resetOffTime(this._scene_tag);
                OffLineManager.instance.resetSceneOffLineGetCoin(this._scene_tag);
                GameEvent.ev(GameEV.off_npc_ui_get_reward, this._off_line_reward * 2);
                this._close();
                StorageManager.instance.keyPointRecord.offlineDouble++;
                StorageManager.instance.keyPointRecord.offlineCoin += this._off_line_reward * 2;
                StorageManager.instance.keyPointRecord.offlinetime++;
            };
            let fail = () => {
                this.btnlock = false;
            };
            SDKManager.instance.ShareOrVideo(ShareLoc.offline_double, success, fail);
        }
        _level_up_video() {
            if (this.btn_video_up.gray) {
                UIMng.instance.createTips(`已经满级`);
                this.redTip.visible = false;
                return;
            }
            let success = () => {
                OffLineManager.instance.setSceneOffLineGetCoin(this._scene_tag, this._off_line_reward);
                OffLineManager.instance.resetOffTime(this._scene_tag);
                OffLineManager.instance.addOffLv(this._scene_tag);
                this._refresh();
            };
            SDKManager.instance.ShareOrVideo(ShareLoc.offline_rise, success);
        }
        _level_up_coin() {
            if (this.btn_coin_up.gray) {
                UIMng.instance.createTips(`已经满级`);
                return;
            }
            let up_coin = OffLineManager.instance.get_up_level_data(this._scene_tag);
            if (StorageManager.instance.Coin < up_coin) {
                UIMng.instance.createCoinTips();
                return;
            }
            StorageManager.instance.Coin -= up_coin;
            OffLineManager.instance.setSceneOffLineGetCoin(this._scene_tag, this._off_line_reward);
            OffLineManager.instance.resetOffTime(this._scene_tag);
            OffLineManager.instance.addOffLv(this._scene_tag);
            this._refresh();
        }
        _close() {
            GameEvent.ev(GameEV.off_npc_talk_end);
            UIMng.instance.closeUIScene(UIScene.offLineDialog);
        }
    }

    class palaceGateDialogUI extends ui.ui_dialog.palaceGateDialogUI {
        constructor() {
            super(...arguments);
            this._enough = false;
        }
        onAwake() {}
        onEnable() {
            L3D.onclick(this.bg, this, this._bg);
            L3D.onclick(this.btnClose, this, this._close);
            L3D.onclick(this.btnYes, this, this._yes);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this._bg);
            L3D.offclick(this.btnClose, this, this._close);
            L3D.offclick(this.btnYes, this, this._yes);
        }
        onOpened(info) {
            if (info) {
                switch (info.type) {
                    case palaceGateType.gateEnterScene2:
                        this.tip1Label.text = '“身份地位不足，无法进入内城，请速速离开” ';
                        this.tip2Label.text = '至少到达【秀女】级别';
                        break;
                    case palaceGateType.gateEnterScene3:
                        if (StorageManager.instance.Level < 14 ||
                            StorageManager.instance.SocialStatus < 50000) {
                            this.tip1Label.text = '“皇宫重地：身份和地位不足者，无法进入”';
                            this.tip2Label.text = '至少达到【美人】级别和5万地位';
                        } else {
                            this.tip1Label.text = '“皇宫正在被不明人士控制”';
                            this.tip2Label.text = '后续再开放';
                        }
                        break;
                    case palaceGateType.gateEnterScene4:
                        if (StorageManager.instance.Level < 27 ||
                            StorageManager.instance.SocialStatus < 300000) {
                            this._enough = false;
                            this.tip1Label.text = '“登基大殿：身份地位不足者，无法进入”';
                            this.tip2Label.text = '至少达到【女皇】级别和30万地位';
                        } else {
                            this._enough = true;
                            this.tip1Label.text = '“皇宫被迷烟包围暂时无法前往登基大殿”';
                            this.tip2Label.text = '需皇宫全部恢复才能前往';
                        }
                        break;
                }
            }
        }
        _close() {
            UIMng.instance.closeUIScene(UIScene.palaceGateDialog);
            GameEvent.ev(GameEV.closeDialog, UIScene.palaceGateDialog);
        }
        _bg() {}
        _yes() {
            let cb = () => __awaiter(this, void 0, void 0, function* () {
                this._close();
                yield GameMgr.currentSceneCtrl.reset(this._enough);
            });
            if (GameMgr.sceneTag == SceneTag.mainGame) {
                TransitionManager.openTransitionType = TransitionEnum.common;
            } else {
                TransitionManager.openTransitionType = TransitionEnum.palace;
            }
            UIMng.instance.openUIScene(UIScene.transitionScene, UIZorder.dig, cb);
        }
    }

