    class BezierMove extends Laya.Script {
        constructor() {
            super(...arguments);
            this._timer = 1000;
        }
        onAwake() {
            this._root = this.owner;
        }
        init(start_pos, middle_pos, end_pos, timer) {
            this._start_pos = start_pos;
            this._middle_pos = middle_pos;
            this._end_pos = end_pos;
            this._timer = timer;
        }
        onStart() {
            Laya.Tween.to(this, {
                factor: 1
            }, this._timer, Laya.Ease.linearInOut, new Laya.Handler(this, () => {
                this.destroy();
            }));
        }
        get factor() {
            return 0;
        }
        set factor(value) {
            this._root.x = (1 - value) * (1 - value) * this._start_pos.x + 2 * value * (1 - value) * this._middle_pos.x + value * value * this._end_pos.x;
            this._root.y = (1 - value) * (1 - value) * this._start_pos.y + 2 * value * (1 - value) * this._middle_pos.y + value * value * this._end_pos.y;
        }
    }

