    class ImgFilter extends Laya.Script {
        static gray(roleImg) {
            let grayscaleMat = [
                0.3, 0.6, 0.1, 0, 0,
                0.3, 0.6, 0.1, 0, 0,
                0.3, 0.6, 0.1, 0, 0,
                0, 0, 0, 1, 0
            ];
            var grayscaleFilter = new Laya.ColorFilter(grayscaleMat);
            roleImg.filters = [grayscaleFilter];
        }
        static colorFilter(img, r, g, b, a = 1) {
            let filter = new Laya.ColorFilter();
            let get_f = filter.color(r, g, b, a);
            img.filters = [get_f, get_f];
        }
        static gaussBlur(img, radius, sigma) {
            let text = img.source;
            let pixes = text.getPixels(0, 0, text.width, text.height);
            let height = text.height,
                width = text.width;
            radius = radius || 5;
            sigma = sigma || radius / 3;
            let gaussEdge = radius * 2 + 1;
            let gaussMatrix = [],
                gaussSum = 0,
                a = 1 / (2 * sigma * sigma * Math.PI),
                b = -a * Math.PI;
            for (let i = -radius; i <= radius; i++) {
                for (let j = -radius; j <= radius; j++) {
                    let gxy = a * Math.exp((i * i + j * j) * b);
                    gaussMatrix.push(gxy);
                    gaussSum += gxy;
                }
            }
            let gaussNum = (radius + 1) * (radius + 1);
            for (let i = 0; i < gaussNum; i++) {
                gaussMatrix[i] / gaussSum;
            }
            let handleEdge = (i, x, w) => {
                let m = x + i;
                if (m < 0) {
                    m = -m;
                } else if (m >= w) {
                    m = w + i - x;
                }
                return m;
            };
            for (var x = 0; x < width; x++) {
                for (var y = 0; y < height; y++) {
                    let r = 0,
                        g = 0,
                        b = 0;
                    for (var i = -radius; i <= radius; i++) {
                        var m = handleEdge(i, x, width);
                        for (var j = -radius; j <= radius; j++) {
                            var mm = handleEdge(j, y, height);
                            var currentPixId = (mm * width + m) * 4;
                            var jj = j + radius;
                            var ii = i + radius;
                            r += pixes[currentPixId] * gaussMatrix[jj * gaussEdge + ii];
                            g += pixes[currentPixId + 1] * gaussMatrix[jj * gaussEdge + ii];
                            b += pixes[currentPixId + 2] * gaussMatrix[jj * gaussEdge + ii];
                        }
                    }
                    var pixId = (y * width + x) * 4;
                    pixes[pixId] = ~~r;
                    pixes[pixId + 1] = ~~g;
                    pixes[pixId + 2] = ~~b;
                }
            }
            let text2 = new Laya.Texture2D(width, height, Laya.TextureFormat.R8G8B8A8, false, false);
            text2.setPixels(pixes);
            img.source = new Laya.Texture(text2);
        }
    }

    class shop2_item_ctr extends Laya.Script {
        constructor() {
            super(...arguments);
            this._root = null;
            this._lab_buy_times = null;
            this._img = null;
            this._btn_info = null;
            this._btn_get = null;
            this._img_costtype = null;
            this._lab_cost = null;
            this._config_id = 0;
            this._config = null;
            this._index = 0;
        }
        onAwake() {
            this._root = this.owner;
            this._lab_buy_times = this._root.getChildByName("lab_buy_times");
            this._img = this._root.getChildByName(`img`);
            this._btn_info = this._root.getChildByName(`btn_info`);
            this._btn_get = this._root.getChildByName(`btn_get`);
            this._img_costtype = this._btn_get.getChildByName("img_costtype");
            this._img_costtype.scale(0.5, 0.5);
            this._lab_cost = this._btn_get.getChildByName("lab_cost");
            this._btn_info.on(Laya.Event.CLICK, this, this._on_info);
            this._btn_get.on(Laya.Event.CLICK, this, this._on_get);
        }
        get config_id() {
            return this._config_id;
        }
        refresh_item(config, index) {
            this._index = index;
            this._config = config;
            this._config_id = config.propid;
            this._img.skin = `assets_compose/${this._config_id}.png`;
            this._img_costtype.skin = `assets_common/${config.costtype}_icon.png`;
            this._lab_cost.text = `${config.cost}`;
            this._lab_buy_times.text = `${StorageManager.instance.shop2_buy_times[this._index]}/5`;
            if (StorageManager.instance.shop2_buy_times[this._index] >= 5) {
                ImgFilter.gray(this._btn_get);
            } else {
                this._btn_get.filters = [];
            }
            if (config.costtype == cost_type_enum.coin) {
                this._btn_get.skin = `assets_compose2/按钮.png`;
            } else {
                this._btn_get.skin = `assets_compose2/按钮2.png`;
            }
        }
        _on_info() {
            UIMng.instance.openUIScene(UIScene.composeInfoDig, UIZorder.dig, this._config_id);
        }
        _on_get() {
            if (StorageManager.instance.shop2_buy_times[this._index] >= 5) {
                UIMng.instance.createTips("次数已达到上限");
                return;
            }
            if (this._config.costtype == cost_type_enum.coin && StorageManager.instance.Coin < this._config.cost) {
                UIMng.instance.createTips("金币不足");
                return;
            }
            if (this._config.costtype == cost_type_enum.yuxi && StorageManager.instance.YuXi < this._config.cost) {
                UIMng.instance.createTips("玉玺不足");
                return;
            }
            if (this._config.costtype == cost_type_enum.coin) {
                StorageManager.instance.Coin -= this._config.cost;
            } else {
                StorageManager.instance.YuXi -= this._config.cost;
            }
            ComposeManaget.inst.push_into_temp_box(this._config_id);
            StorageManager.instance.shop2_buy_times[this._index]++;
            this._lab_buy_times.text = `${StorageManager.instance.shop2_buy_times[this._index]}/5`;
            if (StorageManager.instance.shop2_buy_times[this._index] >= 5) {
                ImgFilter.gray(this._btn_get);
            }
            StorageManager.instance.sync_compose_storage();
        }
    }

