            L3D.offmove(this, this, this._cameraAdjust);
            GameEvent.off(GameEV.showButton, this, this._refreshButton);
            GameEvent.off(GameEV.orderComplete, this, this._orderCompleteEvent);
            GameEvent.off(GameEV.isPlayerFull, this, this._isPlayerFull);
