    class JoyStick extends Laya.Script {
        constructor() {
            super(...arguments);
            this._radius = 100;
        }
        onAwake() {
            this._root = this.owner;
            this._joyListenBox = this._root.getChildByName("JoyListenBox");
            this._joyPanel = this._root.getChildByName("JoyPanel");
            this._point = this._joyPanel.getChildByName("point");
            this._joyPanel.x = Laya.stage.width / 2;
            this._joyPanel.y = Laya.stage.height * 0.8;
        }
        onEnable() {
            L3D.ondown(this._joyListenBox, this, this._onMouseDown);
            L3D.onmove(Laya.stage, this, this._onMouseMove);
            L3D.onup(this._joyListenBox, this, this._onMouseUp);
            GameEvent.on(GameEV.Joy_End, this, this._end);
        }
        onDisable() {
            L3D.offdown(this._joyListenBox, this, this._onMouseDown);
            L3D.onmove(Laya.stage, this, this._onMouseMove);
            L3D.offup(this._joyListenBox, this, this._onMouseUp);
            this._onMouseUp();
            GameEvent.off(GameEV.Joy_End, this, this._end);
        }
        _onMouseDown(e) {
            this._touchId = e.touchId;
            this._joyPanel.x = e.stageX;
            this._joyPanel.y = e.stageY;
        }
        _onMouseMove(e) {
            if (e.touchId !== this._touchId)
                return;
            let jp = this._getJoyPoint(e);
            if (jp.x == 0 && jp.y == 0)
                return;
            this._point.x = -jp.x + 100;
            this._point.y = -jp.y + 100;
            GameEvent.ev(GameEV.Joy_Move, jp);
        }
        _onMouseUp() {
            this._touchId = null;
            this._joyPanel.x = Laya.stage.width / 2;
            this._joyPanel.y = Laya.stage.height * 0.8;
            this._point.x = 100;
            this._point.y = 100;
            GameEvent.ev(GameEV.Joy_End, null);
        }
        _end() {
            this._touchId = null;
            this._joyPanel.x = Laya.stage.width / 2;
            this._joyPanel.y = Laya.stage.height * 0.8;
            this._point.x = 100;
            this._point.y = 100;
        }
        _getJoyPoint(e) {
            let dir = new Laya.Vector3();
            let panelV3 = new Laya.Vector3(this._joyPanel.x, 0, this._joyPanel.y);
            let pointV3 = new Laya.Vector3(e.stageX, 0, e.stageY);
            Laya.Vector3.subtract(panelV3, pointV3, dir);
            let dis = Laya.Vector3.distance(panelV3, pointV3);
            if (dis > this._radius) {
                Laya.Vector3.normalize(dir, dir);
                Laya.Vector3.scale(dir, this._radius, dir);
            }
            let joyPoint = {
                x: dir.x,
                y: dir.z
            };
            return joyPoint;
        }
    }

