    class gameLadderUI extends ui.ui_game.gameLadderUI {
        constructor() {
            super();
            this._game_ctr = null;
            this._color_box = [];
            this._name_box = [];
            this._player_head = null;
            this._player_name = null;
            this._is_can_move_name_box = false;
            this._down_timer = 3;
        }
        onOpened(param) {
            this._game_ctr = param[0];
            for (let i = 0; i < 5; i++) {
                let box = this.getChildByName(`color_${i}`);
                this._color_box.push(box);
                let name_box = this.getChildByName(`name_${i}`);
                this._name_box.push(name_box);
                if (i == this._game_ctr.player_color) {
                    this._player_head = name_box.getChildAt(0).getChildAt(0).getChildByName("head");
                    this._player_name = name_box.getChildAt(0).getChildByName("name");
                }
            }
            this._init_player_name();
            this._init_name_box().then((res) => {
                console.log("初始化玩家昵称头像结束", res);
                this._is_can_move_name_box = res;
            });
            Laya.timer.frameLoop(1, this, this.onUpdate);
            UIMng.instance.openUIScene(UIScene.gameEnterTipDialog, UIZorder.dig, SceneTag.game_ladder);
        }
        _init_player_name() {
            this._player_name.text = `${InfoManager.nick_name}`;
            this._player_head.skin = InfoManager.avatar_url;
            if (!InfoManager.avatar_url) {
                this._player_head.skin = `assets_farmGame/默认头像.png`;
                this._player_name.text = `未授权`;
            }
            if (InfoManager.avatar_url) {
                SDKManager.instance.tt_drawImg(this._player_head, InfoManager.avatar_url);
            }
        }
        _init_name_box() {
            return __awaiter(this, void 0, void 0, function* () {
                return new Promise((reslove) => __awaiter(this, void 0, void 0, function* () {
                    SDKManager.instance.getLuckyUsers(5, (res) => {
                        let list = res;
                        if (!list || list.length < 5)
                            reslove(false);
                        list = list.filter((item) => {
                            return item.nickname != InfoManager.nick_name;
                        });
                        for (let i = 0; i < 5; i++) {
                            if (i == this._game_ctr.player_color)
                                continue;
                            let item = list[Util.RandomInt(0, list.length)];
                            list = list.filter((v) => {
                                return v.nickname != item.nickname;
                            });
                            if (!item.avatar) {
                                item.avatar = `assets_farmGame/默认头像.png`;
                            }
                            if (!item.nickname) {
                                item.nickname = "未授权用户#";
                            }
                            this._name_box[i].getChildAt(0).getChildAt(0).getChildByName("head").skin = `${item.avatar}`;
                            this._name_box[i].getChildAt(0).getChildByName("name").text = `${item.nickname}`;
                        }
                        reslove(true);
                    }, () => {
                        reslove(false);
                    });
                }));
            });
        }
        onUpdate() {
            if (!this._game_ctr || !this._game_ctr.color_targetP || !this._game_ctr.cameraCtrl.camera)
                return;
            if (!this._color_box.length || this._color_box.length < 5)
                return;
            for (let i = 0; i < this._color_box.length; i++) {
                let sp3d = this._game_ctr.color_targetP[i];
                let box = this._color_box[i];
                if (sp3d && sp3d.upMover && sp3d.upMover.numChildren || this._game_ctr.game_over) {
                    box.visible = false;
                } else {
                    box.visible = true;
                }
                let out = new Laya.Vector4();
                let target = sp3d.root.transform.position.clone();
                let camera = this._game_ctr.cameraCtrl.camera;
                target.y += 3;
                camera.viewport.project(target, camera.projectionViewMatrix, out);
                box.x = out.x;
                box.y = out.y;
                if (this._is_can_move_name_box) {
                    let name_box = this._name_box[i];
                    name_box.x = out.x;
                    name_box.y = out.y;
                    if (i == this._game_ctr.player_color) {
                        name_box.y -= 50;
                    }
                }
            }
        }
        onEnable() {
            L3D.onclick(this.btn_back, this, this._back);
            GameEvent.on(GameEV.gameTipStart, this, this.startGame);
        }
        onDisable() {
            L3D.offclick(this.btn_back, this, this._back);
            GameEvent.on(GameEV.gameTipStart, this, this.startGame);
        }
        startGame() {
            this.countDownContent.visible = true;
            this._down_time();
        }
        _down_time() {
            if (this._down_timer <= 0) {
                this.countDownContent.visible = false;
                return;
            }
            Laya.timer.once(1000, this, () => {
                if (this._down_timer > 0) {
                    this._down_timer--;
                    this.timeNumFontClip.value = `${this._down_timer}`;
                    this.ani1.play(0, false);
                }
                this._down_time();
            });
        }
        onAwake() {}
        _back() {
            return __awaiter(this, void 0, void 0, function* () {
                GameMgr.is_changing = true;
                let cb = () => __awaiter(this, void 0, void 0, function* () {
                    yield GameMgr.changeScene(SceneTag.mainGame2);
                    GameMgr.is_changing = false;
                });
                UIMng.instance.closeUIScene(UIScene.gameLadder);
                UIMng.instance.openUIScene(UIScene.mainGame, UIZorder.scene);
                yield UIMng.instance.openUIScene(UIScene.transitionScene, UIZorder.transition, cb);
            });
        }
    }

