            GameEvent.on(GameEV.guideScene2Complete, this, this._guideScene2Complete);
            GameEvent.on(GameEV.fish, this, this._fishEvent);
            GameEvent.on(GameEV.fishBtn, this, this._fishBtnEvent);
            GameEvent.on(GameEV.showButton, this, this._refreshButton);
