        _changeGameSceneEvent(info) {
            Laya.timer.clearAll(this);
            this.imgPop.visible = false;
            this._popType = null;
            this.tipsFull.visible = false;
            this.popTips.visible = false;
            this.specialEventGp.visible = false;
            this.cameraControl.y = 254;
            this.camAdjustBar.height = 496 * 0.5;
            if (GameMgr.bufftime.player)
                Laya.timer.frameLoop(1, this, this._drawPlayerBuff);
            if (GameMgr.bufftime.staff)
                Laya.timer.frameLoop(1, this, this._drawStaffBuff);
            if (GameMgr.bufftime.production)
                Laya.timer.frameLoop(1, this, this._drawProductionBuff);
            this.initDialog();
            this._startCheckPop();
        }
        _guideSceneComplete() {
            if (!ConfigManager.instance.reportErr) {
                this.btnVideoAdd.visible = true;
                this.btnChangeScene.visible = true;
            }
            this.gpMission.visible = true;
            this._refreshMission();
            this._refreshVideoBtn();
            this._check_dy_btn_visable();
            this._startCheckPop();
            this._checkFriendsButtonShow();
        }
        _hide_gpFog() {
            this.gpFog.visible = false;
        }
        _specialEventRefresh(data) {
            switch (data.type) {
                case specialEventType.fog:
                    if (data.isshow) {
                        if (!this.gpFog.visible) {
                            this.gpFog.visible = true;
                            this.ani14.play(0, true);
                            Laya.timer.once(2000, this, this._hide_gpFog);
                        }
                    } else {
                        Laya.timer.clear(this, this._hide_gpFog);
                        this.gpFog.visible = false;
                    }
                    break;
                default:
                    break;
            }
        }
        _on_home_unlock() {
            return __awaiter(this, void 0, void 0, function* () {
                if (this._is_open_unlockhome)
                    return;
                if (GuideScene3Manager.instance.GuideIndex <= 23)
                    return;
                this._is_open_unlockhome = true;
                let unlock_cb = () => {
                    this.btn_home_unlock.visible = false;
                    Laya.timer.clear(this, this._home_unlock_position);
                    GameEvent.ev(GameEV.refreshGuide);
                };
                yield UIMng.instance.openUIScene(UIScene.HomeUnlockDig, UIZorder.dig, unlock_cb);
                this._is_open_unlockhome = false;
            });
        }
        _home_unlock_position() {
            let ctrl = GC.gm.currentSceneCtrl;
            if (!GameMgr.currentSceneCtrl)
                return;
            if (!ctrl.CameraCtrl || !ctrl.CameraCtrl.camera)
                return;
            if (!ctrl.homeCtrl || !ctrl.homeCtrl.buildPos)
                return;
            let pos_vec = ctrl.homeCtrl.buildPos.transform.position.clone();
            pos_vec.y += 4;
            let pos = Util.ThreeD2TwoD(GameMgr.currentSceneCtrl.CameraCtrl.camera, pos_vec);
            this.btn_home_unlock.pos(pos.x, pos.y);
        }
        _cameraAdjust(e) {
            if (e.touchId == this._cameraTouchId) {
                if (!GameMgr.currentSceneCtrl)
                    return;
                let point = new Laya.Point(e.stageX, e.stageY);
                let pos = this.cameraControlGp.globalToLocal(point);
                if (pos.y < 25)
                    pos.y = 25;
                if (pos.y > 483)
                    pos.y = 483;
                this.cameraControl.y = pos.y;
                let rate = (pos.y) / 508;
                this.camAdjustBar.height = 496 * (1 - rate);
                GameMgr.currentSceneCtrl.CameraCtrl.camera.orthographicVerticalSize = 18 + 36 * (1 - rate);
            }
        }
        _startCameraControl(e) {
            if (!StorageManager.instance.guideScene3Complete)
                return;
            this._cameraTouchId = e.touchId;
        }
        _stopCameraControl() {
            this._cameraTouchId = null;
        }
        _refreshCoin() {
            this.fcCoin.value = "" + StorageManager.instance.Coin;
            this.upgradeTips.visible = StorageManager.instance.Coin >= 100;
        }
        _refreshSocialStatus() {
            this.fcStatus.value = "" + StorageManager.instance.SocialStatus;
        }
        _refreshLevel() {
            let config = RoleLevelManager.instance.getConfigByLevel(StorageManager.instance.Level);
            this.levelImg.skin = `assets_common/level_${config.textid}.png`;
            this.imgStatus.skin = `assets_common/character/queen_${config.modelid}.png`;
            this._init_rank_ui();
            this._refreshVideoBtn();
        }
        _upgrade() {
            let config = RoleLevelManager.instance.getConfigByLevel(StorageManager.instance.Level + 1);
            if (!config) {
                UIMng.instance.createTips("已经满级了");
                return;
            }
            UIMng.instance.openUIScene(UIScene.levelUpDialog, UIZorder.dig, this.status_up_tip.visible);
            this.status_up_tip.visible = false;
        }
