    class GridItem extends Laya.Script {
        constructor() {
            super(...arguments);
            this._root = null;
            this._icon = null;
            this._blackMask = null;
            this._layer = -1;
            this._state = GridState.none;
            this._type = gridIconType.type0;
            this._dir = '';
            this._bottomIndex = -1;
            this._curLayer = -1;
            this._stack = false;
            this._originPos = new Laya.Vector2(0, 0);
        }
        get Root() {
            return this._root;
        }
        get RootZorder() {
            return this._root.zOrder;
        }
        get Type() {
            return this._type;
        }
        get State() {
            return this._state;
        }
        get Layer() {
            return this._layer;
        }
        get CurLayer() {
            return this._curLayer;
        }
        get Dir() {
            return this._dir;
        }
        get BottomIndex() {
            return this._bottomIndex;
        }
        get isStack() {
            return this._stack;
        }
        get OriginPos() {
            return this._originPos;
        }
        set isStack(value) {
            this._stack = value;
        }
        set OriginPos(value) {
            this._originPos = value;
        }
        set RootZorder(value) {
            this._root.zOrder = value;
        }
        onAwake() {
            this._root = this.owner;
            this._root.anchorX = 0.5;
            this._root.anchorY = 0.5;
        }
        onEnable() {
            L3D.ondown(this._root, this, this._touchStart);
            L3D.onup(this._root, this, this._touchEnd);
            L3D.onout(this._root, this, this._touchCancel);
        }
        onDisable() {
            L3D.offdown(this._root, this, this._touchStart);
            L3D.offup(this._root, this, this._touchEnd);
            L3D.offout(this._root, this, this._touchCancel);
        }
        onStart() {
            this.OriginPos = new Laya.Vector2(this._root.x, this._root.centerY);
        }
        _touchStart() {
            if (this._state != GridState.active) {
                return;
            }
            this._root.zOrder = GameSheepManager.instance.zOrder++;
            this._root.updateZOrder();
            Laya.Tween.to(this._root, {
                scaleX: 1.2,
                scaleY: 1.2,
            }, 0.1);
        }
        _touchEnd() {
            if (this._state != GridState.active) {
                return;
            }
            GameEvent.ev(GameEV.gridSelect, this);
        }
        _touchCancel() {
            if (this._state != GridState.active) {
                return;
            }
            Laya.Tween.to(this._root, {
                scaleX: 1,
                scaleY: 1,
            }, 100);
        }
        initItem(info) {
            this._state = info.state;
            this._layer = info.layer;
            this._curLayer = info.layer;
            this._dir = info.dir;
            this._bottomIndex = (typeof info.bottomIndeX) == "number" ? info.bottomIndeX : -1;
            this._root.zOrder = this._curLayer;
            this.setType(info.type);
            this._blackMask = new Laya.Image();
            this._blackMask.skin = "assets_dialog/黑色遮罩.png";
            this.owner.addChild(this._blackMask);
            this._blackMask.width = GameSheepManager.gridW;
            this._blackMask.height = GameSheepManager.gridH;
            this._blackMask.centerX = 0;
            this._blackMask.centerY = 0;
            this._blackMask.visible = false;
        }
        changeLayer(layer) {
            this._curLayer = layer;
            this._root.zOrder = this._curLayer;
        }
        setType(type) {
            this._type = type;
            if (!this._icon) {
                this._icon = new Laya.Image();
                this.owner.addChild(this._icon);
                this._icon.width = 70;
                this._icon.height = 70;
                this._icon.centerX = 0;
                this._icon.centerY = -2;
            }
            this._icon.skin = GameSheepManager.instance.getUrlByType(type);
        }
        updateGrid() {
            let allGrids = GameSheepManager.instance.allGridArray;
            let isCover = false;
            for (var i = 0; i < allGrids.length; i++) {
                if (this._state != GridState.idle &&
                    this._state != GridState.active &&
                    this._state != GridState.cover)
                    continue;
                let checkGrid = allGrids[i];
                if (checkGrid.State != GridState.idle &&
                    checkGrid.State != GridState.active &&
                    checkGrid.State != GridState.cover) {
                    continue;
                }
                let tX = Math.abs(this._root.x - checkGrid.Root.x);
                let tY = Math.abs(this._root.y - checkGrid.Root.y);
                if (tX <= GameSheepManager.gridW / 2 && tY <= GameSheepManager.gridH / 2) {
                    if (this._root.zOrder < checkGrid.RootZorder) {
                        isCover = true;
                        this.setState(GridState.cover);
                        break;
                    } else {
                        this.setState(GridState.active);
                    }
                } else {
                    this.setState(GridState.active);
                }
            }
            this._blackMask.visible = isCover;
        }
        moveGrid(info, callBack, time = 100) {
            if (!info ||
                !this._root) {
                return;
            }
            let tweenInfo = {};
            Object.assign(tweenInfo, info);
            let targetX = info.x ? info.x : this._root.x;
            let targetY = info.y ? info.y : this._root.y;
            let centerX = info.centerX ? info.centerX : this._root.centerX;
            let centerY = info.centerY ? info.centerY : this._root.centerY;
            let scaleX = info.scaleX ? info.scaleX : this._root.scaleX;
            let scaleY = info.scaleY ? info.scaleY : this._root.scaleY;
            Laya.Tween.to(this._root, tweenInfo, time, null, Laya.Handler.create(this, () => {
                callBack && callBack();
            }));
        }
        deleteSelf() {
            this.setState(GridState.delete);
            Laya.Tween.to(this._root, {
                scaleX: 1.2,
                scaleY: 1.2,
            }, 100, null, Laya.Handler.create(this, () => {
                Laya.Tween.to(this._root, {
                    scaleX: 0.2,
                    scaleY: 0.2,
                    alpha: 0,
                    rotation: 90,
                }, 200, null, Laya.Handler.create(this, () => {
                    this._root.visible = false;
                }));
            }));
        }
        setState(state) {
            this._state = state;
        }
    }

