    class TransitionUI extends ui.ui_game.transitionSceneUI {
        onAwake() {
            switch (TransitionManager.openTransitionType) {
                case TransitionEnum.common:
                    this.leftDoor.skin = "assets_transition/door.jpg";
                    this.rightDoor.skin = "assets_transition/door.jpg";
                    break;
                case TransitionEnum.palace:
                    this.leftDoor.skin = "assets_transition/door_palace.jpg";
                    this.rightDoor.skin = "assets_transition/door_palace.jpg";
                    break;
                case TransitionEnum.MysteriousEntrance:
                    break;
            }
        }
        onEnable() {
            L3D.onclick(this.bg, this, this.clickbg);
        }
        onDisable() {
            L3D.offclick(this.bg, this, this.clickbg);
        }
        clickbg() {}
        onOpened(promise) {
            this.leftDoor.x = -(Laya.stage.width / 2);
            this.rightDoor.x = Laya.stage.width / 2 * 3;
            if (TransitionManager.openTransitionType == TransitionEnum.compound) {
                this.palace_close.play(0, false);
                this.transitionLR.visible = false;
                this.transitionUD.visible = true;
            } else {
                let target_left = (Laya.stage.width - 750) / 2;
                let target_right = (Laya.stage.width - 750) / 2 + 750;
                Laya.Tween.to(this.leftDoor, {
                    x: target_left
                }, 200);
                Laya.Tween.to(this.rightDoor, {
                    x: target_right
                }, 200);
                this.transitionLR.visible = true;
                this.transitionUD.visible = false;
            }
            Laya.timer.once(1000, this, () => __awaiter(this, void 0, void 0, function* () {
                yield promise();
                if (TransitionManager.openTransitionType == TransitionEnum.compound) {
                    this.palace_open.play(0, false);
                } else {
                    let target_left = -(Laya.stage.width / 2);
                    let target_right = Laya.stage.width / 2 * 3;
                    Laya.Tween.to(this.leftDoor, {
                        x: target_left
                    }, 200);
                    Laya.Tween.to(this.rightDoor, {
                        x: target_right
                    }, 200);
                }
                Laya.timer.once(1000, this, () => {
                    TransitionManager.openTransitionType = TransitionEnum.common;
                    UIMng.instance.closeUIScene(UIScene.transitionScene);
                });
            }));
        }
    }

