    class EffectManager {
        constructor() {
            this._effectList = {};
        }
        static get Instance() {
            if (EffectManager._instance == null)
                EffectManager._instance = new EffectManager();
            return EffectManager._instance;
        }
        init() {
            let alleffect = Laya.Loader.getRes(GC.gm.lh_effect);
            if (!alleffect)
                return;
            for (let i = 0; i < alleffect.numChildren; i++) {
                let effect = alleffect.getChildAt(i);
                let effectname = alleffect.getChildAt(i).name;
                this._effectList[effectname] = effect;
            }
        }
        prewarm() {
            for (let i in this._effectList) {
                let effectname = i;
                let c = this.getEffect(i);
                c.transform.localPositionY = 100;
                GC.gm.currentSceneCtrl.scene.addChild(c);
                Laya.timer.once(1200, this, () => {
                    c.removeSelf();
                    EffectManager.Instance.recovereffect(effectname, c);
                });
            }
        }
        getEffect(effectname) {
            if (!this._effectList[effectname])
                return null;
            let effect = Laya.Pool.getItem(effectname) || this._effectList[effectname].clone();
            if (effect && effect.transform) {
                effect.transform.localPosition = new Laya.Vector3(0, 0, 0);
            }
            return effect;
        }
        recovereffect(efffectname, effect) {
            try {
                if (effect) {
                    effect.removeSelf();
                    Laya.Pool.recover(efffectname, effect);
                }
            } catch (error) {}
        }
    }
