            if (this._characterAnimationController)
                this._characterAnimationController.changeStatus(ModelAction.wash);
            let conf = ProductManager.instance.getProductionActionData(productType.laundry);
            let time = conf.proptime * 1000 * count;
            ctrl.productionClothes(count);
