    class CustomerProductController extends Laya.Script3D {
        constructor() {
            super(...arguments);
            this._state = productState.idle;
            this._moving = false;
            this._target = null;
            this._targetRoot = null;
        }
        get root() {
            return this._root;
        }
        get PropRoot() {
            return this._propModel;
        }
        get Type() {
            return this._type;
        }
        get State() {
            return this._state;
        }
        get Target() {
            return this._target;
        }
        init(type, sceneCtrl) {
            this._state = productState.idle;
            this._moving = false;
            this._sceneCtrl = sceneCtrl;
            this._type = type;
            this._target = null;
        }
        onAwake() {
            this._root = this.owner;
            this._propModel = this._root.getChildByName("prop");
            this._root.transform.localPosition = new Laya.Vector3(0, 0, 0);
            this._root.transform.localRotationEuler = new Laya.Vector3(0, 0, 0);
            Laya.Tween.to(this._propModel.transform, {
                localScaleX: 1.5,
                localScaleY: 1.5,
                localScaleZ: 1.5
            }, 100);
            Laya.timer.once(100, this, () => {
                Laya.Tween.to(this._propModel.transform, {
                    localScaleX: 1,
                    localScaleY: 1,
                    localScaleZ: 1
                }, 100);
            });
        }
        onUpdate() {
            if (!this._type || !GC.gm.isgaming)
                return;
            if (this._moving) {
                this._move();
            }
        }
        _move() {
            if (!(this._target && this._targetRoot && this._targetRoot.transform) || !this._moving)
                return;
            let own_pos = this._root.transform.position.clone();
            let target_pos = this._targetRoot.transform.position.clone();
            let dir = new Laya.Vector3();
            Laya.Vector3.subtract(target_pos, own_pos, dir);
            Laya.Vector3.normalize(dir, dir);
            let distance = Util.twoPointDistance({
                x: own_pos.x,
                y: own_pos.z
            }, {
                x: target_pos.x,
                y: target_pos.z
            });
            if (distance < 0.6) {
                this.addToTarget();
            } else {
                let newPos = new Laya.Vector3();
                Laya.Vector3.add(own_pos, dir, newPos);
                this._root.transform.position = newPos;
            }
        }
        addToTarget() {
            if (!(this._root && this._root.transform))
                return;
            this._root.removeSelf();
            this._root.destroy();
        }
        toCustomer(target) {
            this._moving = true;
            this._state = productState.moving;
            this._target = target;
            this._targetRoot = target.root;
        }
    }

