    class StaffPassController extends StaffController {
        init(scene, id) {
            super.init(scene, id);
            let conf = StaffManager.instance.getConfigById(id);
            this._rackCtrl = scene.propRacks[conf.workid[0]][0];
        }
        stopmove() {
            this.isgoingtotarget = false;
            Laya.Tween.clearAll(this.tweenObj);
            this.refreshAni();
            switch (this.state) {
                case staffState.takingProduction:
                    this.root.transform.localRotationEulerY = this.targetAngel;
                    this.takingProduction();
                    break;
                case staffState.walkToRack:
                    this.root.transform.localRotationEulerY = this.targetAngel;
                    this._rackCtrl.staffComing(this);
                    break;
                case staffState.tostandby:
                    this.checkLazy();
                    break;
                case staffState.drop:
                    this.root.transform.localRotationEulerY = this.targetAngel;
                    this.dropAll();
                    break;
                default:
                    break;
            }
        }
        getProductCtrlFromTop(type) {
            for (let i = 0; i < this.upMover.numChildren; i++) {
                let child = this.upMover.getChildAt(i);
                let ctrl = child.getComponent(ProductController);
                if (ctrl && ctrl.State == productState.inStaffHand) {
                    return ctrl;
                }
            }
            return null;
        }
        removeProduct(p) {
            super.removeProduct(p);
            if (this.number <= 0 && this._rackCtrl) {
                this._rackCtrl.staffLeave();
            }
        }
        walkToDrop() {
            super.walkToDrop();
            if (this._rackCtrl) {
                this._rackCtrl.staffLeave();
            }
        }
    }

