    class StaffZhengrongController extends StaffController {
        constructor() {
            super(...arguments);
            this._patrolIndex = 1;
            this._uiparam = "";
        }
        patrol() {
            let ctrl = GC.gm.currentSceneCtrl.propRacks[productType.zhengrong][0];
            if (ctrl && ctrl.State == productionState.working) {
                if (this._patrolIndex >= StorageManager.instance.zhengronglevel) {
                    this.standby();
                    return;
                }
                for (let i = this._patrolIndex; i < StorageManager.instance.zhengronglevel; i++) {
                    let name = "zhengrong_" + i;
                    if (ctrl.customerInside.includes(name)) {
                        let targetpos = ctrl.playerPos.getChildByName(name);
                        if (targetpos) {
                            this._patrolIndex++;
                            this._uiparam = name;
                            this.changeState(staffState.takingMaterial);
                            let pos = targetpos.transform.position;
                            this.setTargetPoint(pos, 180);
                            return;
                        }
                    }
                }
            }
            this.standby();
        }
        stopmove() {
            this.isgoingtotarget = false;
            Laya.Tween.clearAll(this.tweenObj);
            this.refreshAni();
            switch (this.state) {
                case staffState.takingMaterial:
                    this.root.transform.localRotationEulerY = this.targetAngel;
                    Laya.timer.once(200, this, this.putface);
                    Laya.timer.once(1000, this, this.patrol);
                    break;
                case staffState.tostandby:
                    this.checkLazy();
                    break;
                default:
                    break;
            }
        }
        putface() {
            let ctrl = GC.gm.currentSceneCtrl.propRacks[productType.zhengrong][0];
            if (ctrl.customerInside.includes(this._uiparam)) {
                GameEvent.ev(GameEV.changeModel, {
                    pos: this._uiparam,
                    isplayer: false
                });
            }
        }
        standby(time) {
            super.standby(time);
            this._patrolIndex = 1;
        }
    }

