                    let pos1 = `pos_${pos_name_index}`;
                    pos_name_index++;
                    let pos2 = `pos_${pos_name_index}`;
                    pos_name_index++;
                    ctrl.set_tea_pos_name([pos1, pos2]);
                    this.tableCtrl[pos1] = ctrl;
                    this.tableCtrl[pos2] = ctrl;
