                    empty_pos.addChild(afther_fish);
                    afther_fish.transform.localPosition = new Laya.Vector3(0, 0, 0);
                    this._cur_fish2_num--;
                    this.to_cao_fish(isplayer, out_cb);
                    console.log("生成炒鱼");
                    if (isplayer)
                        MissionManager.instance.missionCheck(missionType.putMaterial, "yushan");
