            if (d > 100) {
                d = 16;
            }
            if (this._lockVideoTime > 0) {
                this._lockVideoTime -= d;
            }
            if (!StorageManager.instance.guideScene3Complete)
                return;
            if (this._aicount >= RoleLevelManager.instance.Guestnums)
                return;
            this._currentTime += d;
            if (this._currentTime > this._cd) {
                this._checkProduction();
            }
            if (this._is_into_fog) {
                this._into_fog_timer += d;
                if (this._into_fog_timer >= 2000) {
                    this._to_reset_player_pos();
                }
            }
