                    let is_add = false;
                    for (let key in StorageManager.instance.goodsProgress) {
                        if (key.includes(type_name)) {
                            let product_coin_num = productCoinNum[type_name] || 0;
                            if (product_coin_num > 0 && !is_add) {
                                unlock_rack_num++;
                                is_unlock = true;
                                is_add = true;
                            }
                        }
                    }
                    if (!this._can_get_coin_ctr[i]) {
                        this._can_get_coin_ctr[i] = [];
                    }
