    class SocialStatusManager {
        static get instance() {
            if (SocialStatusManager._instance == null)
                SocialStatusManager._instance = new SocialStatusManager();
            return SocialStatusManager._instance;
        }
        init() {
            return new Promise((resolve, reject) => __awaiter(this, void 0, void 0, function* () {
                for (let i in StorageManager.instance.saleProgress) {
                    let b_name = i.substring(0, i.indexOf("_"));
                    let b_level = Number(i.substring(i.indexOf("_") + 1));
                    let type = productName.indexOf(b_name);
                    let conf = ProductManager.instance.getSaleAreaData(type);
                    if (conf && conf.statusadd && conf.statusadd.length > 0) {
                        StorageManager.instance.SocialStatus += conf.statusadd[b_level - 1];
                    }
                }
                for (let i in StorageManager.instance.productionProgress) {
                    let b_name = i.substring(0, i.indexOf("_"));
                    let b_level = Number(i.substring(i.indexOf("_") + 1));
                    let type = productName.indexOf(b_name);
                    let conf = ProductManager.instance.getProductionAreaData(type);
                    StorageManager.instance.SocialStatus += conf.statusadd[b_level - 1];
                }
                for (let i in StorageManager.instance.staffs) {
                    let config = StaffManager.instance.getConfigById(Number(i));
                    if (config) {
                        let level = StorageManager.instance.staffs[config.id].level;
                        for (let j = 0; j <= level; j++) {
                            StorageManager.instance.SocialStatus += config.statusadd[j];
                        }
                    }
                }
                for (let i in StorageManager.instance.productionLevelInfo) {
                    let level = StorageManager.instance.productionLevelInfo[i];
                    if (level > 1) {
                        let b_name = i.substring(0, i.indexOf("_"));
                        let config = UpgradeModeManager.instance.getInfoByBuildID("p_" + b_name);
                        if (level == 2) {
                            StorageManager.instance.SocialStatus += config.upgradestatus[0];
                        } else {
                            StorageManager.instance.SocialStatus += (config.upgradestatus[0] + config.upgradestatus[1]);
                        }
                    }
                }
                for (let i in StorageManager.instance.saleLevelInfo) {
                    let level = StorageManager.instance.saleLevelInfo[i];
                    if (level > 1) {
                        let b_name = i.substring(0, i.indexOf("_"));
                        let config = UpgradeModeManager.instance.getInfoByBuildID("s_" + b_name);
                        if (level == 2) {
                            StorageManager.instance.SocialStatus += config.upgradestatus[0];
                        } else {
                            StorageManager.instance.SocialStatus += (config.upgradestatus[0] + config.upgradestatus[1]);
                        }
                    }
                }
                StorageManager.instance.SocialStatus += StorageManager.instance.RewardSocialStatus;
                resolve();
            }));
        }
    }
    SocialStatusManager._instance = null;

